/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A13 checkpoint 1/4: castigate–catharsis (20 frozen headwords). */
'use strict';
const D=globalThis.RA.D;
const q=(w,n,s,p,options,answer,explain)=>({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt:p,options,answer,explain});
const m=(wrong,right,reason)=>({errorType:'meaning',wrong,right,reason});
const c=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const e=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${encodeURIComponent(w.toLowerCase())}`});
D('castigate',{etymology:e('castigate 经法语进入英语，源自拉丁语 castigare“纠正、惩戒”，由 castus“纯正”与 agere“驱使、做”构成；现指严厉批评或惩罚。','castigate'),contexts:[c('castigate.s1','新闻评论','The inquiry did not merely question the minister; it castigated him in public for ignoring repeated warnings about the unsafe bridge.','调查不只是质询部长，还因他无视桥梁安全警告而当众严厉谴责他。','The inquiry did not merely question the minister / it castigated him in public / for ignoring repeated warnings about the unsafe bridge.','castigate 是谓语，for 后的动名词短语说明谴责原因。','公开严厉责备体现 castigate 的批评义 s1。')],mistakes:[m('The editor cast her for the mistake by quietly correcting one comma and offering no criticism.','The editor chastised her for the mistake by quietly correcting one comma and offering no criticism.','castigate 表示严厉谴责或惩罚；轻轻改逗号并未作严厉批评。')],quiz:[q('castigate',1,1,'A newspaper that castigates an official is most likely to?',['condemn the official severely','praise the official warmly','describe the official neutrally'],'condemn the official severely','castigate.s1 指严厉批评，常用于公开谴责。'),q('castigate',2,2,'A school may castigate a student by?',['punishing the student harshly','giving the student a medal','asking the student to leave early as a reward'],'punishing the student harshly','castigate.s2 是严厉惩罚义。'),q('castigate',3,1,'Which verb best fits a report that sharply denounces a policy?',['castigate','congratulate','catalogue'],'castigate','严厉抨击政策可用 castigate。'),q('castigate',4,2,'The coach castigated the player for deliberate cheating. Here castigated means?',['punished or reprimanded severely','selected for the team','taught a new skill'],'punished or reprimanded severely','for cheating 而受严厉斥责或处罚，匹配 s2。')]});
D('casting',{etymology:e('casting 是 cast 加名词后缀 -ing；cast 的“投、倒入模具”义形成铸造物，“挑选演员”义则发展出选角活动。','casting'),contexts:[c('casting.s1','制造工程','The aluminum casting was inspected for trapped air before workers bolted it into the pump housing.','工人把铝铸件装入泵壳前，先检查其中是否有气孔。','The aluminum casting was inspected for trapped air / before workers bolted it into the pump housing.','casting 是 was inspected 的主语，指模具成形的铝制零件。','铝件经检查后装入机械，明确体现铸件义 s1。')],mistakes:[m('The director announced the metal casting of the lead actor after auditions, naming who would play each role.','The director announced the casting of the lead actor after auditions, naming who would play each role.','这里说的是挑选演员，应写 casting，不是金属铸件 metal casting。')],quiz:[q('casting',1,1,'A metal casting is an object made by?',['pouring material into a mould and letting it harden','cutting a sheet into paper shapes','weaving separate threads together'],'pouring material into a mould and letting it harden','casting.s1 指把材料倒入模具后成形的铸件。'),q('casting',2,2,'A film’s casting department is responsible for?',['choosing actors for roles','building the cinema seats','editing the soundtrack'],'choosing actors for roles','casting.s2 是为影视角色挑选演员。'),q('casting',3,1,'The foundry rejected a casting because it had a crack. The word names?',['a mould-formed metal piece','the group of actors in a play','a fishing rod'],'a mould-formed metal piece','铸造厂因铸件裂纹而拒收，符合 s1。'),q('casting',4,2,'After auditions, the casting of a new play is?',['the selection of its performers','the printing of its tickets','the writing of its reviews'],'the selection of its performers','选角是决定哪些演员扮演各个角色。')]});
D('catabolism',{etymology:e('catabolism 由希腊语 katabolē“投下、分解”经新拉丁语形成，和 anabolic（合成代谢）相对；生物学中指分解复杂物质并释放能量的代谢过程。','catabolism'),contexts:[c('catabolism.s1','生物化学','During fasting, catabolism breaks stored glycogen and fat into smaller molecules, making chemical energy available to the body.','禁食期间，分解代谢把储存的糖原和脂肪分解成较小分子，使身体能够利用化学能。','During fasting / catabolism breaks stored glycogen and fat into smaller molecules / making chemical energy available to the body.','catabolism 作主语；breaking ... into 表示分解为。','大分子被拆成小分子并释放可用能量，符合代谢义。')],mistakes:[m('Catabolism builds amino acids into new muscle proteins and stores energy in the newly formed tissue.','Anabolism builds amino acids into new muscle proteins and stores energy in the newly formed tissue.','把小分子合成复杂组织属于 anabolism；catabolism 是分解过程。')],quiz:[q('catabolism',1,1,'Catabolism is the part of metabolism that generally?',['breaks complex molecules down','builds larger molecules from small ones','stores unchanged food in the stomach'],'breaks complex molecules down','catabolism 指分解代谢，而合成过程为 anabolism。'),q('catabolism',2,1,'What commonly happens to energy during catabolic reactions?',['it is released from broken-down molecules','it disappears because no chemical bonds change','it is created from nothing'],'it is released from broken-down molecules','分解代谢通常释放化学能。'),q('catabolism',3,1,'Breaking stored fat into smaller compounds is an example of?',['catabolism','photosynthesis','pollination'],'catabolism','脂肪分解为小分子是分解代谢。'),q('catabolism',4,1,'Which process is opposite in broad direction to catabolism?',['anabolism','oxidation','diffusion'],'anabolism','anabolism 合成大分子，与分解代谢方向相反。')]});
D('cataclysm',{etymology:e('cataclysm 经拉丁语来自希腊语 kataklysmos“洪水、冲刷”，与 klyzein“冲洗”有关；英语后扩展为社会政治的剧烈巨变。','cataclysm'),contexts:[c('cataclysm.s1','地质灾害','The eruption triggered a cataclysm that buried coastal villages under ash and sent survivors fleeing inland.','火山喷发引发一场大灾难，海岸村庄被火山灰掩埋，幸存者逃往内陆。','The eruption triggered a cataclysm / that buried coastal villages under ash / and sent survivors fleeing inland.','that 从句说明 cataclysm 造成的后果。','喷发造成大范围毁灭，体现自然灾难义 s1。')],mistakes:[m('The constitutional cataclysm was a routine change of office furniture that left the political system entirely untouched.','The constitutional adjustment was a routine change of office furniture that left the political system entirely untouched.','轻微、没有政治影响的日常事项不构成 cataclysm。')],quiz:[q('cataclysm',1,1,'A geological cataclysm is?',['a violent disaster causing great damage','a mild change in the weather','a scheduled laboratory test'],'a violent disaster causing great damage','自然灾害中的 cataclysm 是剧烈且破坏性极强的事件。'),q('cataclysm',2,2,'A political cataclysm would involve?',['a sudden, far-reaching upheaval','a quiet weekly meeting','a minor spelling correction'],'a sudden, far-reaching upheaval','cataclysm.s2 比喻政治社会剧变。'),q('cataclysm',3,1,'Which event is most plausibly a cataclysm?',['an earthquake that destroys several cities','a shop changing its opening hour','a student replacing one notebook'],'an earthquake that destroys several cities','跨城市的毁坏性地震属于大灾难。'),q('cataclysm',4,2,'The old regime ended in a cataclysm. The noun describes?',['a violent social transformation','a stable period with no change','a small personal preference'],'a violent social transformation','政权剧变对应社会政治义。')]});
D('catalysis',{etymology:e('catalysis 由 catalyst 加化学过程后缀 -lysis 构成；其词根经希腊语 katalysis“解开、分解”，化学义由 Berzelius 于19世纪提出。','catalysis'),contexts:[c('catalysis.s1','化学实验','The catalysis occurred at the metal surface: the reaction accelerated, but the catalyst could still be recovered afterward.','催化作用发生在金属表面：反应速度加快，但之后仍可回收催化剂。','The catalysis occurred at the metal surface / the reaction accelerated / but the catalyst could still be recovered afterward.','but 连接反应加速与催化剂未被消耗两项事实。','催化剂促进反应却未被耗尽，说明是化学义 s1。')],mistakes:[m('The enzyme caused catalysis by being consumed as the main fuel and disappearing completely in each reaction.','The enzyme caused catalysis by speeding the reaction without being consumed by it.','催化剂促进反应而不被反应净消耗；把它当燃料消耗混淆了催化与反应物。')],quiz:[q('catalysis',1,1,'In chemical catalysis, a catalyst typically?',['speeds a reaction without being used up overall','becomes the only final product','prevents every molecule from reacting'],'speeds a reaction without being used up overall','催化剂加快反应，反应前后通常不被净消耗。'),q('catalysis',2,2,'A “catalysis of reform” in politics is?',['a factor that helps reform happen sooner','a chemical container for political documents','a rule that permanently stops all change'],'a factor that helps reform happen sooner','比喻义指促成、加速某种改变的因素。'),q('catalysis',3,1,'An enzyme speeds a reaction and remains available afterward. This illustrates?',['catalysis','evaporation','sedimentation'],'catalysis','酶促进反应且仍可继续作用，属于催化。'),q('catalysis',4,2,'In “her report provided a catalysis for debate,” catalysis means?',['a stimulus that accelerated discussion','a record that ended discussion','a unit for measuring paper'],'a stimulus that accelerated discussion','报告推动讨论加速，体现比喻性的助推义。')]});
D('catalyze',{etymology:e('catalyze 由 catalyst 加动词后缀 -ize 构成；该科学词与19世纪的 catalysis 同源，表示催化化学反应，后引申为促成变化。','catalyze'),contexts:[c('catalyze.s2','社会改革','A single leaked document catalyzed public debate, bringing officials, residents, and journalists together to demand an investigation.','一份泄露的文件促成了公众辩论，使官员、居民和记者共同要求调查。','A single leaked document catalyzed public debate / bringing officials, residents, and journalists together / to demand an investigation.','catalyzed 后接事件作宾语；分词短语说明引发的结果。','文件推动公共辩论更快发生，符合引申义 s2。')],mistakes:[m('The proposal catalyzed no discussion because it immediately caused a vigorous debate among every department.','The proposal catalyzed discussion because it immediately caused a vigorous debate among every department.','引发激烈辩论说明 proposal 促成了讨论，不能同时说 catalyzed no discussion。')],quiz:[q('catalyze',1,1,'A substance that catalyzes a reaction?',['makes the reaction proceed faster','is necessarily destroyed before it starts','changes the reaction into a political speech'],'makes the reaction proceed faster','化学义 catalyze 指借助催化剂使反应加快。'),q('catalyze',2,2,'A crisis may catalyze negotiations by?',['causing them to begin or move faster','making all participants forget the issue','turning negotiations into a chemical element'],'causing them to begin or move faster','引申义是促成或加速某个进程。'),q('catalyze',3,1,'Which event could catalyze a public inquiry?',['new evidence that prompts officials to investigate','a file that no one sees and that changes nothing','a report unrelated to any decision'],'new evidence that prompts officials to investigate','促使调查启动的新证据可 catalyze 调查。'),q('catalyze',4,2,'In “the discovery catalyzed a new research program,” catalyzed means?',['set the program in motion','formally cancelled the program','measured the program’s budget'],'set the program in motion','发现促成研究计划启动，符合 s2。')]});
D('cataract',{etymology:e('cataract 经拉丁语 cataracta 源自希腊语 kataraktēs“瀑布、闸门”，来自 katarrhaktēs“向下冲”；同一英语词也指眼晶状体混浊。','cataract'),contexts:[c('cataract.s2','眼科','The surgeon removed the cataract from her cloudy lens, then replaced it with an artificial lens so she could read road signs again.','外科医生摘除了她混浊晶状体上的白内障，并植入人工晶体，使她能重新看清路标。','The surgeon removed the cataract from her cloudy lens / then replaced it with an artificial lens / so she could read road signs again.','cataract 是 removed 的宾语；so 引出手术结果。','晶状体混浊并以手术治疗，体现眼科义 s2。')],mistakes:[m('The ophthalmologist diagnosed a cataract as a steep waterfall in the patient’s eye lens that clouded her vision.','The ophthalmologist diagnosed a cataract as a cloudy area in the patient’s eye lens that blurred her vision.','瀑布义是地理景观；眼科诊断必须指晶状体混浊。')],quiz:[q('cataract',1,1,'An eye cataract is a clouding of the?',['lens','eardrum','kneecap'],'lens','白内障是眼晶状体混浊。'),q('cataract',2,2,'A cataract on a river is?',['a large waterfall or rushing drop','a shallow pond with no current','a bridge across dry land'],'a large waterfall or rushing drop','地理义 cataract 指大瀑布或急流落差。'),q('cataract',3,1,'An older patient who sees through a cloudy lens may have?',['a cataract','a sprained ankle','a hearing loss'],'a cataract','晶状体混浊、视物模糊是白内障的典型描述。'),q('cataract',4,2,'“The cataract roared below the cliffs” most likely refers to?',['a powerful waterfall','an eye operation','a lens implant'],'a powerful waterfall','在悬崖下轰鸣的 cataract 是瀑布义。')]});
D('catastrophic',{etymology:e('catastrophic 由 catastrophe 加形容词后缀 -ic 构成；catastrophe 经法语源自希腊语 katastrophē“翻转、结局”，古典戏剧中指情节的终局。','catastrophic'),contexts:[c('catastrophic.s1','工程安全','A catastrophic failure of the dam would flood three towns, so inspectors shut the reservoir gates after finding a deep structural crack.','大坝若发生灾难性故障会淹没三座城镇，因此检查人员发现深层结构裂缝后关闭了水库闸门。','A catastrophic failure of the dam would flood three towns / so inspectors shut the reservoir gates / after finding a deep structural crack.','catastrophic 修饰 failure；so 表示风险导致采取措施。','可能造成巨大毁坏和伤亡的故障属于灾难性后果 s1。')],mistakes:[m('The team called the minor typo catastrophic even though nobody noticed it and the report remained accurate.','The team called the minor typo harmless because nobody noticed it and the report remained accurate.','没有造成严重损害或失败的细小笔误不宜称 catastrophic。')],quiz:[q('catastrophic',1,1,'A catastrophic error is one that?',['causes terrible damage or failure','has no consequence at all','is a routine harmless adjustment'],'causes terrible damage or failure','catastrophic.s1 强调极严重的破坏性后果。'),q('catastrophic',2,2,'“The launch was catastrophic” can mean it was?',['an utter failure','a modest success','a carefully planned rehearsal'],'an utter failure','s2 可形容结果糟糕、彻底失败。'),q('catastrophic',3,1,'Which is a catastrophic consequence of a toxic leak?',['many residents are poisoned and evacuated','one label is printed in a slightly different font','a clerk changes a meeting time'],'many residents are poisoned and evacuated','大量中毒并疏散是灾难性损害。'),q('catastrophic',4,2,'A catastrophic defeat is best described as?',['a devastating loss','a narrow win','a tie with no effect'],'a devastating loss','彻底惨败符合“糟透了、毁灭性”的引申义。')]});
D('catching',{etymology:e('catching 是 catch 加 -ing 构成的形容词；catch 经古法语与拉丁语 captare“追逐、捕捉”进入英语，此处发展为疾病或情绪能传播。','catching'),contexts:[c('catching.s2','音乐欣赏','The children were humming the chorus all afternoon because its catching rhythm was easy to remember after hearing it once.','孩子们整个下午都在哼那段副歌，因为它的旋律很有感染力，听过一次就容易记住。','The children were humming the chorus all afternoon / because its catching rhythm was easy to remember / after hearing it once.','catching 修饰 rhythm；because 引出反复哼唱的原因。','旋律悦耳、容易传播到听众心中，体现 s2 的感染力。')],mistakes:[m('The doctor said the catching infection could not spread to anyone who shared the same room.','The doctor said the noncontagious infection could not spread to anyone who shared the same room.','既然不会传播，就不应称 catching（易传染的）。')],quiz:[q('catching',1,1,'A catching illness is one that?',['can spread from one person to another','cannot be transmitted under any conditions','affects only plants'],'can spread from one person to another','catching.s1 表示疾病容易传染。'),q('catching',2,2,'A catching tune is?',['so appealing that people readily remember or repeat it','too quiet for anyone to hear','a song that cannot be learned'],'so appealing that people readily remember or repeat it','catching.s2 描写容易使人喜欢或跟着唱的旋律。'),q('catching',3,1,'Which is a catching yawn?',['one person yawns and nearby people soon do too','a person reads a silent sign','a door locks itself'],'one person yawns and nearby people soon do too','哈欠在人群中传播体现 catching 的感染性。'),q('catching',4,2,'The comedian’s laugh was catching because?',['the audience soon began laughing too','nobody in the room could hear it','it stopped every joke from being told'],'the audience soon began laughing too','笑声引得别人也笑，体现情绪的感染力。')]});
D('catchment',{etymology:e('catchment 由 catch 加名词后缀 -ment 构成，原指汇集雨水的区域；随后借用为学校、医院等机构吸引服务对象的范围。','catchment'),contexts:[c('catchment.s2','教育规划','The new secondary school was placed near the edge of its catchment, allowing pupils from four villages to reach it by bus.','新中学建在招生服务范围的边缘附近，让四个村子的学生都能乘公交到校。','The new secondary school was placed near the edge of its catchment / allowing pupils from four villages to reach it by bus.','catchment 是 its 的中心名词；分词短语说明选址带来的便利。','学生来自该校的招生范围，体现 s2。')],mistakes:[m('Rain from the catchment drained away from the reservoir into a separate ocean basin and never reached the river.','Rain from the watershed drained away from the reservoir into a separate ocean basin and never reached the river.','如果讨论雨水流入河流的土地范围，应称 catchment/watershed；原句与水库的 catchment 关系前后不符。')],quiz:[q('catchment',1,1,'A river catchment is the area where rainfall?',['drains toward that river','falls only on the open sea','is stored in a household bottle'],'drains toward that river','catchment.s1 指汇水并流入河流的流域。'),q('catchment',2,2,'A school catchment determines?',['which area the school serves or draws pupils from','how deep the riverbed is','where a film is screened'],'which area the school serves or draws pupils from','学校服务区义说明机构覆盖的地理范围。'),q('catchment',3,1,'A hospital expands its catchment. It is likely to?',['serve patients from a larger area','reduce the amount of rain it collects','stop admitting any patients'],'serve patients from a larger area','扩大 catchment 即扩大服务覆盖区域。'),q('catchment',4,2,'If water from hills flows into one reservoir, those hills form its?',['catchment area','casting call','cataract lens'],'catchment area','汇入水库的土地构成集水区。')]});
D('cate',{etymology:e('cate 是中古英语词，借自古法语或拉丁语 cata“食物、佳肴”；现较罕见，常见于 cates 一类文学表达。','cate'),contexts:[c('cate.s1','文学描写','The travelers welcomed the simple meal after weeks on the road, calling the warm bread and spiced stew welcome cates.','旅人赶了数周路后欢迎这顿简单饭食，把热面包和香料炖菜称为可口佳肴。','The travelers welcomed the simple meal after weeks on the road / calling the warm bread and spiced stew welcome cates.','calling 引出称谓；cates 是 cate 的复数形式。','热面包与炖菜被称作美食，体现罕用名词义。')],mistakes:[m('The menu called a plate of stale, inedible scraps a cate, praising it as a delicious delicacy.','The menu called a plate of fresh pastries a cate, praising it as a delicious delicacy.','cate 指精致或美味食物；不可食用的残渣与“美食”描述相矛盾。')],quiz:[q('cate',1,1,'In older or literary English, a cate is?',['a delicacy or choice food','a type of sailing vessel','a courtroom judgment'],'a delicacy or choice food','cate 是较少见的“佳肴、美食”名词。'),q('cate',2,1,'A host lays out cates for guests. The host has prepared?',['fine foods','maps of the city','tools for building'],'fine foods','cates 是 cate 的复数，指美食。'),q('cate',3,1,'Which could naturally be called a cate?',['a carefully prepared savory pie','a broken shoe','an empty glass'],'a carefully prepared savory pie','精心制作的可口食品符合 cate 的意思。'),q('cate',4,1,'Cate is chiefly a?',['noun','preposition','auxiliary verb'],'noun','词条标为名词，表示佳肴。')]});
D('catechism',{etymology:e('catechism 经晚期拉丁语 catechismus 来自希腊语 katēkhismos“口头教导”，关联 katēkhein“使听到、教导”；原义体现在问答式教义教学。','catechism'),contexts:[c('catechism.s1','宗教教育','The class learned the catechism through a sequence of questions about belief, each followed by a short answer the pupils memorized.','学生通过一系列关于信仰的问题学习教理问答，每个问题后面都有一段需要背诵的简短回答。','The class learned the catechism through a sequence of questions about belief / each followed by a short answer / the pupils memorized.','catechism 是 learned 的宾语；followed by 说明问答配对形式。','关于教义的成套问题和答案直接体现 s1。')],mistakes:[m('The teacher called a random collection of unrelated arithmetic puzzles a catechism of Catholic doctrine.','The teacher called an official sequence of questions and answers about Catholic belief a catechism.','教理问答应系统解释信仰教义；无关算术题不具备该性质。')],quiz:[q('catechism',1,1,'A religious catechism is usually organized as?',['questions and answers explaining doctrine','a collection of maps and travel dates','a set of musical scales only'],'questions and answers explaining doctrine','catechism.s1 是解释宗教教义的问答体系。'),q('catechism',2,1,'A student memorizing a catechism is learning?',['a formal summary of religious teaching','a list of unrelated recipes','the rules of a board game'],'a formal summary of religious teaching','教理问答用于教授并概括信仰教义。'),q('catechism',3,1,'Which text is most likely a catechism?',['a church’s ordered questions about faith with answers','a novel with no teaching questions','a weather chart'],'a church’s ordered questions about faith with answers','有序的信仰问答正是 catechism 的形式。'),q('catechism',4,1,'The older root behind catechism concerns?',['oral instruction','metal casting','water drainage'],'oral instruction','词源关联口头教导，与问答式教学相符。')]});
D('categoric',{etymology:e('categoric 是 category 的形容词形式，借法语或新拉丁语并经希腊语 katēgorikos 而来；逻辑中的 categorical 命题不带条件，故引申为断然明确。','categoric'),contexts:[c('categoric.s1','采访报道','The witness gave a categoric denial, saying she had never seen the missing ledger and would not qualify her statement.','证人断然否认，说自己从未见过那本失踪账簿，也不愿对这番话作任何保留。','The witness gave a categoric denial / saying she had never seen the missing ledger / and would not qualify her statement.','categoric 修饰 denial；saying 分词短语补充否认内容。','毫不含糊、没有条件的否认体现 s1。')],mistakes:[m('The committee issued a categoric answer that might be yes or no depending on several unstated conditions.','The committee issued a conditional answer that might be yes or no depending on several unstated conditions.','依赖未说明条件的答复不是 categoric 的断然、无条件表达。')],quiz:[q('categoric',1,1,'A categoric refusal is?',['firm and unconditional','uncertain and heavily qualified','a request for more information'],'firm and unconditional','categoric 指断然、无条件，毫不含糊。'),q('categoric',2,1,'Which sentence gives a categoric denial?',['“I did not take it, under any circumstances.”','“I may not have taken it, but I am not sure.”','“I need to check before answering.”'],'“I did not take it, under any circumstances.”','绝对且无保留的否认符合 categoric。'),q('categoric',3,1,'A categoric statement leaves?',['no meaningful doubt or condition','several possibilities unresolved','the entire subject unnamed'],'no meaningful doubt or condition','categoric 表达明确坚决，不附条件。'),q('categoric',4,1,'Categoric is closest in meaning to?',['categorical','tentative','ambiguous'],'categorical','categoric 与 categorical 都可表示断然、明确。')]});
D('categorical',{etymology:e('categorical 源自 category 加形容词后缀 -ical，经拉丁语与希腊语 katēgoria“断言、类别”而来；有“断然明确”及“按范畴分类”两组义。','categorical'),contexts:[c('categorical.s3','统计分析','The analyst used categorical variables such as region and language group, rather than continuous measures like age or income.','分析人员使用地区、语言群体等类别变量，而非年龄或收入这类连续数值。','The analyst used categorical variables such as region and language group / rather than continuous measures like age or income.','categorical 修饰 variables；rather than 对比分类变量与连续变量。','地区和语言组把数据分入类别，体现分类义 s3。')],mistakes:[m('The spokesperson made a categorical denial but then listed three exceptions and said the claim might be true after all.','The spokesperson made a qualified denial but then listed three exceptions and said the claim might be true after all.','列出例外并保留可能性，与 categorical 的绝对断然义相冲突。')],quiz:[q('categorical',1,1,'A categorical denial is?',['complete and without exceptions','tentative and full of caveats','a description of a geometric shape'],'complete and without exceptions','categorical.s1 指绝对、没有例外或疑问。'),q('categorical',2,2,'A categorical variable in a data set records?',['membership in a group or class','an unrestricted continuous quantity only','the date a printer was purchased'],'membership in a group or class','categorical.s3 与分类群组相关。'),q('categorical',3,1,'Which reply is categorical?',['“No; I will not approve it under any condition.”','“Possibly, if the figures change.”','“I have not decided yet.”'],'“No; I will not approve it under any condition.”','无条件且明确的拒绝体现 s1。'),q('categorical',4,3,'The phrase “categorical distinction between species” concerns?',['the classes into which they are placed','a firm refusal to answer','an unclear pronunciation'],'the classes into which they are placed','categorical.s3 可指与类别或范畴有关。')]});
D('categorically',{etymology:e('categorically 由 categorical 加副词后缀 -ly 构成；其副词义承接 categorical 的“断然、绝对”及“清楚明确”两种用法。','categorically'),contexts:[c('categorically.s2','法律陈述','In her affidavit, the witness stated categorically that the signature was not hers, leaving no ambiguity about her position.','证人在宣誓书中明确表示那不是自己的签名，对自己的立场没有留下任何模糊空间。','In her affidavit / the witness stated categorically / that the signature was not hers / leaving no ambiguity about her position.','categorically 修饰 stated；that 从句给出明确陈述的内容。','宣誓证词清楚说明事实，体现 s2 的明确地表达。')],mistakes:[m('The witness answered categorically, “I am only guessing and may be wrong,” making clear that she was uncertain.','The witness answered tentatively, “I am only guessing and may be wrong,” making clear that she was uncertain.','表达不确定、可能出错并非 categorically 的断然或明确说法。')],quiz:[q('categorically',1,1,'To deny something categorically is to deny it?',['firmly, with no qualification','quietly, without being heard','by placing it in alphabetical order'],'firmly, with no qualification','categorically.s1 表示断然地、不附条件地。'),q('categorically',2,2,'If a rule is explained categorically, it is explained?',['in words that leave no confusion','with several contradictory meanings','only through a picture'],'in words that leave no confusion','s2 强调表达清楚明确，不会误解。'),q('categorically',3,1,'“She categorically rejected the offer” means she?',['rejected it absolutely','might accept it later','sorted it into a category'],'rejected it absolutely','断然拒绝对应 categorical 的绝对语气。'),q('categorically',4,2,'Which sentence uses categorically to mean clearly?',['The notice categorically states which fees are refundable.','The clerk categorically placed the papers in a drawer.','The train categorically arrived late.'],'The notice categorically states which fees are refundable.','明确列出哪些费用可退体现 categorically.s2。')]});
D('categorisation',{etymology:e('categorisation 是 categorise 加名词后缀 -ation 的英式拼法；categorise 源自 category，意为把事物归入类别。','categorisation'),contexts:[c('categorisation.s1','图书编目','The library revised its categorisation of local history books so that readers could find material by place, period, or subject.','图书馆调整了地方史书籍的分类方式，让读者可按地点、时期或主题查找资料。','The library revised its categorisation of local history books / so that readers could find material / by place, period, or subject.','categorisation 是 revised 的宾语；so that 引出分类调整的目的。','按地点、时期或主题把书籍分组，符合分类义。')],mistakes:[m('The museum’s categorisation left every object ungrouped and deliberately refused to assign items to any class.','The museum’s inventory left every object ungrouped and deliberately refused to assign items to any class.','categorisation 是分组归类；完全不分组应称 inventory 或未分类清单。')],quiz:[q('categorisation',1,1,'Categorisation is the process of?',['putting items into named groups','measuring the length of every item','removing all labels from a collection'],'putting items into named groups','categorisation.s1 即把事物归入类别。'),q('categorisation',2,1,'A library categorises books by subject in order to?',['organize them into useful groups','make each title impossible to locate','change the books’ authors'],'organize them into useful groups','按主题归类便于组织和检索。'),q('categorisation',3,1,'Which is an act of categorisation?',['sorting plants into families by shared traits','counting how many chairs are in a room','weighing a box without labeling its contents'],'sorting plants into families by shared traits','依据共同特征分入植物科属于分类。'),q('categorisation',4,1,'Categorisation most directly produces?',['categories or classes','a chemical catalyst','a legal punishment'],'categories or classes','分类过程将形成类别或组别。')]});
D('caterer',{etymology:e('caterer 由 cater 加施事后缀 -er 构成；cater 经古法语 acater“采购、购买”进入英语，后来专指为活动或机构提供餐饮。','caterer'),contexts:[c('caterer.s1','婚礼筹办','The caterer confirmed a vegetarian menu for the wedding and arranged to deliver hot dishes before the guests arrived.','餐饮承办商为婚礼确认了素食菜单，并安排在宾客到达前送来热菜。','The caterer confirmed a vegetarian menu for the wedding / and arranged to deliver hot dishes / before the guests arrived.','caterer 是 confirmed 的主语；to deliver 表示安排的事项。','为婚礼准备并供应餐食的人或公司就是 caterer。')],mistakes:[m('The caterer was hired to repair the wedding hall’s electrical wiring, but supplied no food or drink.','The electrician was hired to repair the wedding hall’s electrical wiring, but supplied no food or drink.','caterer 的工作是供餐，不是维修电路。')],quiz:[q('caterer',1,1,'A wedding caterer is hired mainly to?',['prepare and supply food for the event','choose the wedding venue’s paint color','write the guests’ speeches'],'prepare and supply food for the event','caterer 是为活动提供餐饮的人或企业。'),q('caterer',2,1,'Which person is a caterer?',['a firm delivering meals to a conference','a photographer taking portraits','a florist arranging bouquets'],'a firm delivering meals to a conference','会议送餐公司承担 catering 工作。'),q('caterer',3,1,'If a caterer confirms a menu, the caterer is confirming?',['which dishes will be provided','who will repair the roof','the date of a court hearing'],'which dishes will be provided','菜单属于餐饮承办的内容。'),q('caterer',4,1,'The suffix -er in caterer identifies?',['a person or business doing the service','a past-tense verb','a place where rain collects'],'a person or business doing the service','-er 在这里构成提供服务者的名词。')]});
D('catering',{etymology:e('catering 是 cater 加 -ing 构成的名词；cater 源自古法语中“采购、供给”的词，英语中发展为为多人或机构筹备餐食的行业。','catering'),contexts:[c('catering.s1','校园服务','The college outsourced catering to a local company that prepares lunch for students and provides refreshments at evening lectures.','学院把餐饮服务外包给一家本地公司，由其为学生做午餐并在晚间讲座提供茶点。','The college outsourced catering to a local company / that prepares lunch for students / and provides refreshments at evening lectures.','catering 是 outsourced 的宾语；that 从句说明承办公司提供的服务。','为多人和活动供应膳食，体现餐饮行业义。')],mistakes:[m('The school’s catering contract covered only the repair of classroom computers and included no food service.','The school’s IT support contract covered only the repair of classroom computers and included no food service.','餐饮服务不涵盖电脑维修；无供餐内容时不应称 catering。')],quiz:[q('catering',1,1,'Catering is the business of?',['providing meals for groups or institutions','designing bridges over rivers','publishing weather forecasts'],'providing meals for groups or institutions','catering.s1 指为多人供应餐食的工作或行业。'),q('catering',2,1,'A company that supplies lunch at a conference provides?',['catering','censorship','cataracts'],'catering','会议供餐属于 catering 服务。'),q('catering',3,1,'A hospital expands its catering service by?',['preparing meals for more patients and staff','adding more surgical beds but no food','printing extra appointment cards'],'preparing meals for more patients and staff','医院 catering 指为病患或员工供应餐食。'),q('catering',4,1,'Which cost most likely belongs under event catering?',['food preparation and service','stage lighting rental only','train tickets for speakers'],'food preparation and service','餐饮承办费用通常包括食物准备和供应。')]});
D('caterpillar',{etymology:e('caterpillar 经古法语 chatepelose 等形式进入英语，早期词形与“毛茸茸的猫”有关；机械义 caterpillar track 因履带节片像毛虫般连续移动而得名。','caterpillar'),contexts:[c('caterpillar.s2','工程车辆','The bulldozer crossed the muddy construction site on a wide caterpillar, spreading its weight across the soft ground.','推土机靠宽大的履带穿过泥泞工地，把重量分散到松软地面上。','The bulldozer crossed the muddy construction site on a wide caterpillar / spreading its weight across the soft ground.','on a wide caterpillar 指履带；分词短语说明履带带来的作用。','此处是 caterpillar track 的简称，即车辆履带义 s2。')],mistakes:[m('The gardener identified the caterpillar as the metal belt wrapped around the tractor’s wheels, not as an insect larva.','The mechanic identified the caterpillar as the metal belt wrapped around the tractor’s wheels, not as an insect larva.','句中描述的是车辆履带，识别者应是机械师；把它称昆虫幼虫会误判语境。')],quiz:[q('caterpillar',1,1,'A butterfly caterpillar is?',['a soft-bodied larva','an adult bird','a metal vehicle belt'],'a soft-bodied larva','caterpillar.s1 指蝴蝶或蛾的幼虫。'),q('caterpillar',2,2,'On a tracked vehicle, a caterpillar is?',['the continuous belt running around its wheels','the driver’s seat','the exhaust pipe'],'the continuous belt running around its wheels','机械义是履带，常简称 caterpillar。'),q('caterpillar',3,1,'Leaves with bite marks and a small larva may indicate?',['a caterpillar feeding','a caterpillar track turning','a car engine cooling'],'a caterpillar feeding','幼虫取食叶片体现昆虫义。'),q('caterpillar',4,2,'A bulldozer uses caterpillars to?',['move over soft or rough ground','pollinate flowers','measure the height of trees'],'move over soft or rough ground','履带能帮助重型车辆通过松软、不平地面。')]});
D('catharsis',{etymology:e('catharsis 经拉丁语 catharsis 源自希腊语 katharsis“净化、清洗”，与 kathairein“清洁”相关；亚里士多德用它描述悲剧引起的情感净化。','catharsis'),contexts:[c('catharsis.s1','心理与文学','Writing an unsent letter to her late father gave Mei a catharsis: she expressed years of grief and felt calmer afterward.','给已故父亲写一封不寄出的信让梅得到情感宣泄：她说出了多年的悲痛，之后平静了许多。','Writing an unsent letter to her late father gave Mei a catharsis / she expressed years of grief / and felt calmer afterward.','catharsis 是 gave 的宾语；冒号后解释情绪释放和结果。','压抑悲伤得到表达、情绪随后缓解，正是情感宣泄义。')],mistakes:[m('The play caused catharsis by leaving the audience emotionally numb and preventing any release of tension.','The play failed to provide catharsis because it left the audience emotionally numb and prevented any release of tension.','catharsis 是情绪释放并带来缓解；完全没有释放不构成 catharsis。')],quiz:[q('catharsis',1,1,'Catharsis is an emotional experience of?',['releasing pent-up feelings and feeling relief','forgetting how to speak','learning a new instrument'],'releasing pent-up feelings and feeling relief','catharsis.s1 指压抑情绪得到释放后的舒缓。'),q('catharsis',2,1,'A tragic play may provide catharsis when viewers?',['work through strong emotions and feel some release','remain wholly unaffected by the story','memorize the theater’s seating chart'],'work through strong emotions and feel some release','悲剧可能引发情感净化或宣泄。'),q('catharsis',3,1,'Which situation best illustrates catharsis?',['after grieving aloud, someone feels emotionally lighter','someone hides every feeling and becomes more tense','someone calculates a bill'],'after grieving aloud, someone feels emotionally lighter','表达悲伤后感到轻松，体现情绪释放。'),q('catharsis',4,1,'The Greek source of catharsis is associated with?',['cleansing or purification','casting metal','categorizing books'],'cleansing or purification','词源 katharsis 有净化、清洗之意。')]});
D('cathode',{etymology:e('cathode 由 Michael Faraday 于19世纪提出，借希腊语 kathodos“向下的路、下降”命名电流进入电解装置的电极；现代电化学以阴极为还原发生处。','cathode'),contexts:[c('cathode.s1','电化学','At the cathode, copper ions gained electrons and formed a reddish metal coating, while oxidation occurred at the other electrode.','在阴极，铜离子获得电子并形成红色金属镀层；氧化则发生在另一电极。','At the cathode / copper ions gained electrons and formed a reddish metal coating / while oxidation occurred at the other electrode.','at the cathode 标出反应位置；while 对比另一电极的反应。','离子在该电极获得电子、发生还原，符合 cathode 定义。')],mistakes:[m('During electrolysis the cathode is where oxidation occurs, as metal ions lose electrons and become positive.','During electrolysis the anode is where oxidation occurs, as metal atoms lose electrons and become positive ions.','还原发生在 cathode；失电子的氧化发生在 anode。')],quiz:[q('cathode',1,1,'Reduction takes place at the?',['cathode','anode in every possible cell','insulating case'],'cathode','电化学定义中 cathode 是还原发生的电极。'),q('cathode',2,1,'At a cathode, a positive metal ion commonly?',['gains electrons','loses its nucleus','turns into a sound wave'],'gains electrons','得电子即还原，发生在阴极。'),q('cathode',3,1,'Which electrode can acquire a copper coating during electroplating?',['the cathode','the salt bridge only','the power switch'],'the cathode','镀铜时铜离子在阴极还原并沉积。'),q('cathode',4,1,'The cathode is defined by the reaction occurring there, namely?',['reduction','evaporation','combustion'],'reduction','阴极的判定标准是还原反应发生于此。')]});
D('Catholicism',{etymology:e('Catholicism 由 Catholic 加 -ism 构成；Catholic 经拉丁语 catholicus 来自希腊语 katholikos“普遍的、整体的”，后成为罗马天主教会及其信仰的专名。','Catholicism'),contexts:[c('Catholicism.s2','宗教史','The course compared Catholicism’s liturgy, saints, and sacramental practices across several countries while noting local differences in worship.','课程比较了多个国家天主教的礼仪、圣徒和圣事习俗，同时指出各地礼拜方式的差异。','The course compared Catholicism’s liturgy, saints, and sacramental practices / across several countries / while noting local differences in worship.','Catholicism 所有格修饰 liturgy、saints 和 practices；while 表示并行说明。','礼仪与教义实践共同体现 Catholicism.s2。')],mistakes:[m('Catholicism is the Buddhist tradition centered on the Four Noble Truths and the teachings of the Buddha.','Buddhism is the tradition centered on the Four Noble Truths and the teachings of the Buddha.','把佛教教义归给 Catholicism 混淆了两种宗教传统。')],quiz:[q('Catholicism',1,1,'Catholicism is the religious faith associated with?',['the Roman Catholic Church and the Pope in Rome','the Four Noble Truths of Buddhism','the ancient Olympic games'],'the Roman Catholic Church and the Pope in Rome','Catholicism.s1 指以罗马教宗权威为基础的天主教信仰。'),q('Catholicism',2,2,'A study of Catholicism’s ceremonies examines its?',['teachings and worship practices','chemical reactions','forms of government only'],'teachings and worship practices','Catholicism.s2 包括天主教教义、仪式与习俗。'),q('Catholicism',3,1,'A Catholic parish’s religious tradition is part of?',['Catholicism','catharsis','catalysis'],'Catholicism','教区所实践的天主教传统属于 Catholicism。'),q('Catholicism',4,2,'The suffix -ism in Catholicism helps form the name of a?',['belief system or doctrine','single church building','musical instrument'],'belief system or doctrine','-ism 常构成思想、信仰或制度的名称。')]});
D('causal',{etymology:e('causal 经法语或拉丁语 causalis 来自 causa“原因、案件”；形容词因而表示与原因或因果关系有关。','causal'),contexts:[c('causal.s1','医学研究','The researchers found a causal link only after a controlled trial showed that changing the dose reliably changed the patients’ blood pressure.','研究人员直到一项对照试验证明剂量变化会稳定地改变患者血压后，才发现因果联系。','The researchers found a causal link only after a controlled trial showed / that changing the dose reliably changed the patients’ blood pressure.','causal 修饰 link；only after 强调需要对照证据。','研究证明改变一个因素会引起结果变化，体现因果关系。')],mistakes:[m('The study called the two variables causal merely because they rose at the same time, without testing whether either influenced the other.','The study called the two variables correlated merely because they rose at the same time, without testing whether either influenced the other.','同时变化只显示相关性，不能单凭此证明因果关系。')],quiz:[q('causal',1,1,'A causal relationship connects an event with its?',['cause','spelling','postal address'],'cause','causal 表示原因或因果关系方面的。'),q('causal',2,1,'Two measures move together, but no experiment shows one affects the other. The evidence establishes?',['correlation, not a causal link','a proven cause','a language family'],'correlation, not a causal link','相关共变本身不足以证明 causal connection。'),q('causal',3,1,'A causal factor is one that?',['helps bring about an outcome','is merely listed alphabetically','cannot affect anything'],'helps bring about an outcome','causal factor 对结果有促成作用。'),q('causal',4,1,'Which question tests a causal claim?',['Would changing X alter Y?','How many letters are in X?','Is X printed in blue?'],'Would changing X alter Y?','因果主张关心改变原因是否改变结果。')]});
D('causality',{etymology:e('causality 由 causal 加名词后缀 -ity 构成；causal 经拉丁语 causalis 与 causa“原因”相连，causality 指原因产生结果的原理或关系。','causality'),contexts:[c('causality.s1','科学方法','The physicist questioned causality when the signal appeared to arrive before the event that supposedly produced it.','信号似乎早于据称产生它的事件到达时，物理学家对因果关系提出了疑问。','The physicist questioned causality / when the signal appeared to arrive before the event / that supposedly produced it.','causality 是 questioned 的宾语；before 对比原因与结果的时间次序。','讨论一个事件是否产生另一个事件，涉及因果原理。')],mistakes:[m('Causality means that events have no causes and simply occur without any relation to what came before.','Causality concerns the relation in which causes produce or influence events that follow.','无因无果的说法否定了 causality 的核心含义。')],quiz:[q('causality',1,1,'Causality is the principle that?',['events are produced by causes','all events are unrelated by definition','every event is a type of category'],'events are produced by causes','causality.s1 指原因产生或影响事件的原理。'),q('causality',2,1,'A debate about whether A brought about B concerns?',['causality','catering','celery'],'causality','是否由 A 引起 B 属于因果关系问题。'),q('causality',3,1,'Which statement expresses causality?',['The heat caused the ice to melt.','The ice and a book were both blue.','The room had three windows.'],'The heat caused the ice to melt.','句子明确把热作为融化的原因。'),q('causality',4,1,'Causality differs from simple coincidence because it involves?',['a cause-and-effect connection','two events merely sharing a color','an alphabetical sequence'],'a cause-and-effect connection','因果关系比同时发生多了原因与结果的联系。')]});
D('caustic',{etymology:e('caustic 经拉丁语 causticus 来自希腊语 kaustikos“能燃烧的”，源自 kaiein“烧”；既指化学腐蚀性，也比喻尖刻讽刺。','caustic'),contexts:[c('caustic.s2','书评','Her caustic review mocked the director’s grand claims with such sharp wit that the theater’s publicist issued a rebuttal the next morning.','她尖刻的评论用犀利机智嘲讽导演的夸夸其谈，以至于剧院公关第二天一早就发表了反驳。','Her caustic review mocked the director’s grand claims / with such sharp wit / that the theater’s publicist issued a rebuttal the next morning.','caustic 修饰 review；such...that 表示尖刻评论引发的结果。','机智而伤人的批评是 caustic.s2。')],mistakes:[m('The caustic remark praised every colleague warmly and was carefully designed to offend no one.','The complimentary remark praised every colleague warmly and was carefully designed to offend no one.','友善赞扬不是 caustic 的尖刻、伤人话语。')],quiz:[q('caustic',1,1,'A caustic chemical is able to?',['burn or corrode materials','freeze water without cooling it','make metal magnetic'],'burn or corrode materials','caustic.s1 指能化学灼伤或腐蚀的。'),q('caustic',2,2,'A caustic joke is?',['sharply critical and hurtful','gentle and wholly admiring','unrelated to speech or criticism'],'sharply critical and hurtful','caustic.s2 指尖刻、带讽刺性的言辞。'),q('caustic',3,3,'A bottle marked “caustic” should be handled as?',['a corrosive chemical hazard','ordinary drinking water','a soft fabric'],'a corrosive chemical hazard','名词义 caustic 可指腐蚀剂，需谨慎处理。'),q('caustic',4,2,'“His caustic reply stung” means his reply was?',['wittily but painfully critical','a literal chemical solution','a neutral greeting'],'wittily but painfully critical','刻薄的言语会在比喻意义上刺痛听者。')]});
D('cautiously',{etymology:e('cautiously 由 cautious 加副词后缀 -ly 构成；cautious 经拉丁语 cautus“谨慎的、提防的”，源自 cavere“当心”。','cautiously'),contexts:[c('cautiously.s1','野外调查','The survey team moved cautiously across the thin ice, testing each step with a pole before transferring their weight.','调查队员谨慎地穿过薄冰，每走一步都先用杆子试探，再把身体重量移过去。','The survey team moved cautiously across the thin ice / testing each step with a pole / before transferring their weight.','cautiously 修饰 moved；before 引出把重量压上去之前的动作。','先试探再前进以避免危险，符合谨慎义。')],mistakes:[m('She handled the cracked glass cautiously by grabbing it with bare hands and swinging it over the children.','She handled the cracked glass carelessly by grabbing it with bare hands and swinging it over the children.','徒手挥动碎玻璃暴露于明显风险，不能称谨慎地处理。')],quiz:[q('cautiously',1,1,'To approach a potentially dangerous animal cautiously is to approach it?',['carefully to reduce risk','as fast and loudly as possible','without looking at it'],'carefully to reduce risk','cautiously.s1 表示考虑风险、避免出错地小心行动。'),q('cautiously',2,1,'Which action is done cautiously?',['testing a ladder before climbing high','running onto an untested roof','mixing unknown chemicals without protection'],'testing a ladder before climbing high','先检查梯子是在降低危险，体现谨慎。'),q('cautiously',3,1,'The adverb cautiously most directly modifies?',['the manner of an action','the number of objects','the owner of a house'],'the manner of an action','副词 cautious-ly 说明动作如何进行。'),q('cautiously',4,1,'A driver proceeds cautiously in fog because?',['visibility is poor and hazards may be hidden','the road is perfectly visible and empty','the driver wants to ignore all signals'],'visibility is poor and hazards may be hidden','雾中能见度低，慢行观察是谨慎做法。')]});
D('cavalry',{etymology:e('cavalry 经法语 cavalerie 与意大利语 cavalleria 源自拉丁语 caballus“马”；历史上指骑马作战的部队，后来也用于装甲化机动部队。','cavalry'),contexts:[c('cavalry.s1','军事史','The cavalry crossed the open plain on horseback, scouting ahead of the infantry and carrying messages between distant units.','骑兵骑马穿过开阔平原，在步兵前方侦察，并在相距较远的部队之间传递消息。','The cavalry crossed the open plain on horseback / scouting ahead of the infantry / and carrying messages between distant units.','cavalry 是主语；on horseback 说明传统骑兵的行动方式。','骑马作战、侦察的军队体现骑兵义。')],mistakes:[m('The cavalry were infantry soldiers trained exclusively to fight on foot and forbidden to use horses or vehicles.','The infantry were soldiers trained to fight on foot, unlike the historical cavalry mounted on horses.','完全徒步作战属于 infantry；骑兵传统上以骑马作战。')],quiz:[q('cavalry',1,1,'Historically, cavalry troops fought mainly?',['on horseback','from submarines','as unarmed courtroom clerks'],'on horseback','cavalry.s1 指骑马作战的军队。'),q('cavalry',2,1,'A cavalry scout in an older army would likely?',['ride ahead to observe enemy movements','repair ships at a harbor','write laws for a parliament'],'ride ahead to observe enemy movements','骑兵可凭机动性前出侦察。'),q('cavalry',3,1,'Which branch contrasts historically with cavalry?',['infantry fighting on foot','a bakery serving soldiers','a naval lighthouse'],'infantry fighting on foot','infantry 是步兵，与骑兵相对。'),q('cavalry',4,1,'In modern usage, a cavalry unit may also be?',['an armored mobile military unit','a civilian riding school only','a group of hospital nurses'],'an armored mobile military unit','现代 cavalry 也可指装甲机动兵种。')]});
D('cavendish',{etymology:e('Cavendish 烟草名与17世纪英国政治家 Charles Cavendish 的姓氏有关；香蕉品种名来自英国德文郡 Chatsworth House 的 Cavendish 家族，两个用法各有命名史。','cavendish'),contexts:[c('cavendish.s2','食品供应','The grocer ordered Cavendish bananas because their firm yellow skins travel well and the variety is widely sold in supermarkets.','杂货商订购卡文迪许香蕉，因为它们黄色的果皮结实、便于运输，而且这种品种在超市广泛出售。','The grocer ordered Cavendish bananas / because their firm yellow skins travel well / and the variety is widely sold in supermarkets.','Cavendish 作香蕉品种的专名修饰 bananas；because 解释采购原因。','超市常见的黄色甜香蕉品种即 s2。')],mistakes:[m('The tobacconist sold Cavendish tobacco as a fresh yellow dessert banana, peeled and ready to eat.','The grocer sold a Cavendish banana as a fresh yellow dessert fruit, peeled and ready to eat.','烟草义 Cavendish 是压制调制过的烟草，不是水果。')],quiz:[q('cavendish',1,1,'Cavendish tobacco is traditionally?',['sweetened or softened tobacco pressed into cakes','a variety of green tea leaves','a medicinal metal alloy'],'sweetened or softened tobacco pressed into cakes','cavendish.s1 指调制并压制成块的烟草。'),q('cavendish',2,2,'A Cavendish banana is the?',['common yellow dessert banana variety','wild apple from a European oak','type of underground mushroom'],'common yellow dessert banana variety','cavendish.s2 指常见商品香蕉品种。'),q('cavendish',3,2,'Which item would a fruit vendor place among Cavendish?',['yellow bananas for eating fresh','pressed tobacco cakes','a ceramic bowl'],'yellow bananas for eating fresh','水果摊上的 Cavendish 是香蕉品种。'),q('cavendish',4,1,'The tobacco and banana senses of Cavendish are?',['separate named uses with different histories','two spellings of a chemical element','both names for the same fruit'],'separate named uses with different histories','此专名两个义项分别指烟草和香蕉，命名史并不相同。')]});
D('cavort',{etymology:e('cavort 是19世纪美国英语中的动词，词源不确定；常见解释认为它可能受 curvet“马匹腾跃”影响，但来源未能确定。','cavort'),contexts:[c('cavort.s1','动物行为','The foals cavorted around the paddock, leaping sideways and chasing one another whenever the rain stopped.','雨一停，小马驹便在围场里欢腾跳跃、互相追逐。','The foals cavorted around the paddock / leaping sideways and chasing one another / whenever the rain stopped.','cavorted 是动作动词；分词短语列举嬉闹的具体动作。','腾跃、追逐体现兴奋活泼地嬉戏。')],mistakes:[m('The exhausted foals cavorted motionlessly in their stalls and made no playful movement at all.','The exhausted foals rested motionlessly in their stalls and made no playful movement at all.','完全静止休息与 cavort 所指的欢腾跳跃相反。')],quiz:[q('cavort',1,1,'Children cavorting in a field are?',['leaping or playing about energetically','sitting motionless in silence','writing a formal contract'],'leaping or playing about energetically','cavort 指兴奋、嬉闹地腾跃或跑动。'),q('cavort',2,1,'Which scene best fits “the puppies cavorted”?',['they bounced and chased each other','they slept without moving','they stood in a line for inspection'],'they bounced and chased each other','幼犬蹦跳互追是 cavort 的典型场景。'),q('cavort',3,1,'Cavort usually suggests movement that is?',['playful and lively','carefully motionless','mechanically measured and slow'],'playful and lively','该词带有活泼嬉戏的意味。'),q('cavort',4,1,'The etymology of cavort is best described as?',['uncertain, perhaps influenced by a word for a horse’s leap','certainly from the Latin for “cloud”','a modern abbreviation for a computer'],'uncertain, perhaps influenced by a word for a horse’s leap','词源说法不确定；有观点认为与马匹腾跃词 curvet 有关。')]});
D('CD',{etymology:e('CD 是 compact disc 的首字母缩略语；该光盘格式于20世纪后期由 Philips 与 Sony 推广，以激光读取数字音频或数据。','CD'),contexts:[c('CD.s1','音乐收藏','She cleaned the scratched CD carefully, then played the album on an old stereo whose laser could still read the disc.','她小心地擦拭划伤的 CD，然后在一台激光头仍能读取光盘的老式音响上播放专辑。','She cleaned the scratched CD carefully / then played the album on an old stereo / whose laser could still read the disc.','CD 是 cleaned 的宾语，后文明确为激光读取的光盘。','播放音乐的激光读取塑料圆盘体现 CD.s1。')],mistakes:[m('The CD was a paper sheet that stored sound by means of a magnetic needle pressed into grooves.','The vinyl record was a disc that stored sound in grooves read by a stylus.','磁针读取沟槽描述黑胶唱片；CD 以激光读取数字数据。')],quiz:[q('CD',1,1,'A CD is read by?',['a laser','a fountain pen','a compass needle'],'a laser','CD 的数字数据通过激光读取。'),q('CD',2,1,'The initials CD stand for?',['compact disc','central department','chemical deposit'],'compact disc','CD 是 compact disc 的缩写。'),q('CD',3,1,'Which item could contain a music album on a CD?',['a small optical plastic disc','a paper envelope with no recording','a wooden flute'],'a small optical plastic disc','CD 是可存储音频或数据的光盘。'),q('CD',4,1,'Unlike a CD, a vinyl record is normally read by?',['a stylus following grooves','a laser scanning digital pits','a barometer'],'a stylus following grooves','黑胶唱片由唱针读取沟槽，CD 则用激光。')]});
D('CD-ROM',{etymology:e('CD-ROM 是 compact disc read-only memory 的缩写；它把光盘介质与只读存储器的概念组合起来，用于分发电脑软件、文字和图像数据。','CD-ROM'),contexts:[c('CD-ROM.s1','软件分发','The encyclopedia came on a CD-ROM, so the school could install its articles and maps on computers without giving pupils writable discs.','这套百科全书以只读光盘发行，因此学校能把文章和地图安装到电脑上，而不用给学生可写光盘。','The encyclopedia came on a CD-ROM / so the school could install its articles and maps on computers / without giving pupils writable discs.','on a CD-ROM 表示数据介质；so 引出光盘用于安装内容的结果。','光盘存有可由电脑读取但不能改写的数据，符合 CD-ROM。')],mistakes:[m('The museum sold a CD-ROM that visitors could erase and rewrite freely like a blank rewritable disc.','The museum sold a rewritable CD that visitors could erase and rewrite freely.','ROM 是只读存储器；可擦写介质不能称 CD-ROM。')],quiz:[q('CD-ROM',1,1,'ROM in CD-ROM indicates that the disc is?',['read-only memory','a recording microphone','a remote-operated motor'],'read-only memory','ROM 是 read-only memory 的缩写。'),q('CD-ROM',2,1,'A computer can use a CD-ROM to?',['read stored software or reference material','rewrite every stored file at will','print paper without a computer'],'read stored software or reference material','CD-ROM 提供电脑可读取的存储内容。'),q('CD-ROM',3,1,'Which description distinguishes a CD-ROM from a rewritable disc?',['its stored contents are not meant to be rewritten by the user','it contains no data','it is made of paper'],'its stored contents are not meant to be rewritten by the user','CD-ROM 是只读介质，区别于可擦写光盘。'),q('CD-ROM',4,1,'An old language course distributed on a CD-ROM was stored on?',['an optical disc for computer reading','a cassette of magnetic tape only','a sheet of printed newsprint'],'an optical disc for computer reading','CD-ROM 是电脑读取的光盘存储介质。')]});
D('ceaseless',{etymology:e('ceaseless 由 cease 加 -less 构成，字面为“没有停止的”；cease 经古法语 cessier 源自拉丁语 cessare“停止、休止”。','ceaseless'),contexts:[c('ceaseless.s2','城市噪音','Residents complained about the ceaseless traffic noise outside the hospital, which continued through the night and made sleep difficult.','居民抱怨医院外无休止的交通噪声；噪音整夜持续，让人难以入睡。','Residents complained about the ceaseless traffic noise / outside the hospital / which continued through the night / and made sleep difficult.','ceaseless 修饰 noise；which 从句说明噪声持续且令人难受。','令人厌烦、难以忍受的连续噪音体现 s2。')],mistakes:[m('The ceaseless applause lasted for only one brief clap and then stopped for the rest of the evening.','The brief applause lasted for only one brief clap and then stopped for the rest of the evening.','短暂一次就停止的掌声不是 ceaseless。')],quiz:[q('ceaseless',1,1,'Ceaseless effort is effort that?',['continues without stopping','happens only once','is done only by accident'],'continues without stopping','ceaseless.s1 指不停歇、持续不断的。'),q('ceaseless',2,2,'Ceaseless noise that irritates neighbors is?',['annoyingly continuous','silent all night','a single brief sound'],'annoyingly continuous','s2 用于令人烦扰且不停的噪音或争吵。'),q('ceaseless',3,1,'Which is ceaseless?',['a pump that runs day and night without pause','a bell rung once and then removed','a meeting cancelled before it begins'],'a pump that runs day and night without pause','不间断运行符合 ceaseless.s1。'),q('ceaseless',4,2,'The ceaseless argument wore everyone down because it?',['kept going and was hard to bear','ended after one polite sentence','was never actually spoken'],'kept going and was hard to bear','争吵持续不止且令人疲惫，符合 s2。')]});
D('cedar',{etymology:e('cedar 经拉丁语 cedrus 与希腊语 kedros 进入英语；树名古老，常指雪松属植物，也宽泛用于气味芳香、木质耐久的相近针叶树及其木材。','cedar'),contexts:[c('cedar.s2','木工材料','The cabinetmaker lined the drawer with cedar because the fragrant, durable wood helps protect stored woolens from insects.','橱柜工在抽屉内衬上雪松木，因为这种芳香而耐用的木材有助于保护储存的毛织物免受虫害。','The cabinetmaker lined the drawer with cedar / because the fragrant, durable wood / helps protect stored woolens from insects.','cedar 是介词 with 的宾语，后文解释木材特性和用途。','抽屉衬里用的是雪松木，体现木材义 s2。')],mistakes:[m('The carpenter chose cedar because its wood was odorless, fragile, and unsuitable for building or storage.','The carpenter chose cedar because its wood was fragrant and durable, making it useful for building or storage.','雪松木常以芳香、耐久见称；无味易碎的描述不符。')],quiz:[q('cedar',1,1,'A cedar is primarily?',['a large evergreen conifer','a flowering annual herb','a freshwater fish'],'a large evergreen conifer','cedar.s1 指雪松或相似的常绿针叶树。'),q('cedar',2,2,'A chest made of cedar is made from?',['aromatic, durable wood','soft fruit pulp','woven wool'],'aromatic, durable wood','cedar.s2 指树木的木材，常芳香且耐久。'),q('cedar',3,1,'A cedar tree belongs broadly among?',['conifers','mushrooms','insects'],'conifers','雪松是针叶树。'),q('cedar',4,2,'Why might cedar line a storage drawer?',['its scented wood is durable and can deter insects','it dissolves quickly in water','it is a kind of fabric'],'its scented wood is durable and can deter insects','芳香耐久的雪松木常用于箱柜衬里。')]});
D('celebratory',{etymology:e('celebratory 由 celebrate 加形容词后缀 -ory 构成；celebrate 经拉丁语 celebrare“聚集、举行、赞颂”进入英语，现代义与纪念和庆祝活动相关。','celebratory'),contexts:[c('celebratory.s1','团队庆功','After the rescue operation ended successfully, the crew shared a celebratory meal and toasted the volunteers who had worked through the storm.','救援行动成功结束后，队员们共进庆祝晚餐，并向冒着风暴工作的志愿者举杯致意。','After the rescue operation ended successfully / the crew shared a celebratory meal / and toasted the volunteers / who had worked through the storm.','celebratory 修饰 meal；举杯致意说明这顿饭的庆祝性质。','成功后专门举行的晚餐属于庆祝活动。')],mistakes:[m('They held a celebratory dinner to mourn the team’s defeat and mark the end of their season in silence.','They held a memorial dinner to mourn the team’s defeat and mark the end of their season in silence.','哀悼失败的安静晚餐不是表达庆祝的 celebratory event。')],quiz:[q('celebratory',1,1,'A celebratory gathering is held to?',['mark or show happiness about an achievement','punish people for an offense','conduct an ordinary safety inspection'],'mark or show happiness about an achievement','celebratory.s1 指为庆祝某事而举行或表达喜悦的。'),q('celebratory',2,1,'Which is a celebratory gesture after a victory?',['raising a toast to the winning team','issuing a warning for a fire hazard','recording an unpaid invoice'],'raising a toast to the winning team','获胜后举杯祝贺体现庆祝性质。'),q('celebratory',3,1,'A celebratory message would most likely say?',['“Congratulations on your graduation!”','“The valve failed during testing.”','“Your package was delayed.”'],'“Congratulations on your graduation!”','祝贺毕业是在表达庆祝。'),q('celebratory',4,1,'Celebratory differs from celebratory in no spelling but applies to?',['an event or action intended to celebrate','an event intended to criticize','a list of ungrouped items'],'an event or action intended to celebrate','celebratory 修饰与庆祝有关的活动或行为。')]});
D('celery',{etymology:e('celery 经法语 céleri 来自意大利语 seleri，最终可追溯到希腊语 selinon“欧芹、芹属植物”；现代英语指这种茎叶蔬菜及单根茎。','celery'),contexts:[c('celery.s2','烹饪备料','The recipe calls for one celery, chopped into small pieces, to add a crisp, mildly savory bite to the stew.','食谱要求切碎一根芹菜茎，为炖菜增添清脆而微咸香的口感。','The recipe calls for one celery / chopped into small pieces / to add a crisp, mildly savory bite to the stew.','one celery 在此指一根芹菜茎；to add 表示加入的目的。','数量词 one 表明 celery.s2 的单根茎用法。')],mistakes:[m('The cook added one celery, meaning one whole celery plant with its roots, leaves, and many stems removed.','The cook added one celery stalk, meaning a single crisp stem from the plant.','烹饪中 one celery 指一根芹菜茎；若强调完整植株须说明 whole plant。')],quiz:[q('celery',1,1,'Celery is a vegetable with?',['long crisp stems','a hard brown shell and kernel','a single edible root like a potato'],'long crisp stems','celery.s1 指长而脆的芹菜茎类蔬菜。'),q('celery',2,2,'In “add one celery to the soup,” celery can mean?',['one individual stalk','a whole field of vegetables','a bowl used for serving'],'one individual stalk','celery.s2 可指烹饪使用的一根芹菜茎。'),q('celery',3,1,'Which ingredient is celery?',['a pale-green crunchy stalk','a dried coffee bean','a slice of cheddar'],'a pale-green crunchy stalk','芹菜茎通常淡绿、口感清脆。'),q('celery',4,2,'The chef chops two celery for a salad. The count refers to?',['two celery stalks','two entire farms','two kinds of knives'],'two celery stalks','可数用法指两根芹菜茎。')]});
D('celestial',{etymology:e('celestial 经古法语 celestial 源自拉丁语 caelestis“天空的、天国的”，来自 caelum“天空”；既用于天体，也用于宗教天堂及比喻性的绝美。','celestial'),contexts:[c('celestial.s1','天文学','The observatory plotted the celestial bodies visible at dawn, marking the Moon and three bright planets against the eastern horizon.','天文台绘出了黎明时可见的天体，并在东边地平线上标出月亮和三颗明亮行星。','The observatory plotted the celestial bodies visible at dawn / marking the Moon and three bright planets / against the eastern horizon.','celestial 修饰 bodies；分词短语举出可见天体。','月亮和行星属于天空中的天体，体现 s1。')],mistakes:[m('The astronomer called a buried fossil celestial because it had formed deep underground and had never been in the sky.','The astronomer called a planet celestial because it is a body in the sky.','深埋地下的化石不是天体；celestial 的天文学义指天空或天体。')],quiz:[q('celestial',1,1,'Celestial bodies include?',['stars and planets','subterranean roots only','kitchen utensils'],'stars and planets','celestial.s1 指天空中的星体、行星等。'),q('celestial',2,2,'A celestial kingdom in religious writing concerns?',['heaven as the home of God','a government office on Earth','a planet’s chemical composition'],'heaven as the home of God','celestial.s2 指宗教意义上的天国。'),q('celestial',3,3,'A celestial performance praised as “heavenly” is?',['wonderfully beautiful or delightful','scientifically measured from orbit','related only to a tax category'],'wonderfully beautiful or delightful','比喻义 s3 表示美妙得仿佛来自天国。'),q('celestial',4,1,'Which tool studies celestial objects?',['an astronomical telescope','a kitchen thermometer','a soil sieve'],'an astronomical telescope','望远镜用于观察天空中的 celestial objects。')]});
D('cellist',{etymology:e('cellist 由 cello 加表示演奏者的 -ist 构成；cello 是 violoncello 的缩略形式，最终关联意大利语 violone“低音乐器”及 cello“小的”后缀。','cellist'),contexts:[c('cellist.s1','室内乐','The cellist tuned the lowest string before joining the quartet, then carried the melody beneath the violins during the slow movement.','大提琴家加入四重奏前调好了最低的琴弦，并在慢乐章中用大提琴为小提琴托出旋律。','The cellist tuned the lowest string before joining the quartet / then carried the melody beneath the violins / during the slow movement.','cellist 是 tuned 和 carried 的主语；最低弦及与小提琴合奏说明其演奏乐器。','演奏 cello 的音乐家就是 cellist。')],mistakes:[m('The cellist tuned her cello, then handed the instrument to the violinist because she did not play it.','The cellist tuned her cello, then played it beneath the violin melody.','既然她负责调大提琴并演奏，该人物不是“不演奏它”的 violinist。')],quiz:[q('cellist',1,1,'A cellist is a musician who plays the?',['cello','clarinet','cymbals'],'cello','cellist.s1 即大提琴演奏者。'),q('cellist',2,1,'Before an orchestra performs, a cellist may?',['tune the cello’s strings','replace the conductor’s baton','paint the stage scenery'],'tune the cello’s strings','大提琴家会调试其乐器琴弦。'),q('cellist',3,1,'Which musician would sit with a large upright string instrument?',['a cellist','a flutist','a trumpeter'],'a cellist','大提琴通常夹在双膝之间直立演奏。'),q('cellist',4,1,'The suffix -ist in cellist refers to?',['a person who performs or practices something','a past-tense action','a type of wooden case'],'a person who performs or practices something','-ist 构成表示从事某项活动的人。')]});
D('cello',{etymology:e('cello 是意大利语 violoncello 的缩略形式；violoncello 字面上是 violone 的“小型”形式，violone 为低音弦乐器名。','cello'),contexts:[c('cello.s1','乐团排练','She rested the cello’s endpin on the floor, held the neck in her left hand, and drew the bow across its strings.','她把大提琴的尾柱支在地板上，左手扶住琴颈，再用琴弓拉奏琴弦。','She rested the cello’s endpin on the floor / held the neck in her left hand / and drew the bow across its strings.','cello’s 是所有格；三个并列动作展示演奏时如何支撑乐器。','尾柱落地、手持琴弓的弦乐器是大提琴。')],mistakes:[m('The musician tucked the cello under her chin and played it like a small violin.','The musician held the violin under her chin and played it like a small violin.','大提琴直立夹在双膝之间，不像小提琴那样架在下巴下。')],quiz:[q('cello',1,1,'A cello belongs to the?',['violin family of bowed string instruments','brass family of wind instruments','keyboard family of instruments'],'violin family of bowed string instruments','cello.s1 是小提琴家族的大型弓弦乐器。'),q('cello',2,1,'A cellist usually holds the cello?',['upright between the knees','flat on a table under one elbow','over the shoulder like a flute'],'upright between the knees','大提琴直立放在演奏者双膝之间。'),q('cello',3,1,'Which part of a cello rests on the floor?',['the endpin','the bridge of the nose','the tuning fork'],'the endpin','演奏时大提琴的尾柱支撑在地面。'),q('cello',4,1,'The word cello is shortened from the Italian?',['violoncello','caterpillar','cataclysm'],'violoncello','cello 是 violoncello 的缩略形式。')]});
D('cellular',{etymology:e('cellular 由 cell 加形容词后缀 -ular 构成；cell 经拉丁语 cellula“小房间”而来，cellular 后用于生物细胞、蜂窝状结构及蜂窝移动网络。','cellular'),contexts:[c('cellular.s2','电信网络','The cellular network lost service in the valley because no nearby radio station could relay signals to the hikers’ phones.','山谷里的蜂窝移动网络中断了，因为附近没有无线基站能把信号转发到徒步者的手机。','The cellular network lost service in the valley / because no nearby radio station could relay signals / to the hikers’ phones.','cellular 修饰 network；because 解释信号中断的原因。','蜂窝式无线基站向手机转发信号，体现移动通信义 s2。')],mistakes:[m('A cellular network is a wired system with no radio stations, no mobile devices, and no wireless signal coverage.','A cellular network is a wireless system that uses radio stations to provide mobile coverage.','用基站传送无线信号是 cellular network 的定义特征；全有线且无无线覆盖与之矛盾。')],quiz:[q('cellular',1,1,'Cellular biology studies?',['the cells that make up living things','the prices of telephone cables only','the movement of ocean tides'],'the cells that make up living things','cellular.s1 与构成生物体的细胞有关。'),q('cellular',2,2,'A cellular phone network relies on?',['radio stations or cells that relay mobile signals','a single paper letter carrier','undersea plants'],'radio stations or cells that relay mobile signals','蜂窝移动通信依靠基站覆盖区域并转发信号。'),q('cellular',3,3,'A cellular foam has?',['many small spaces like a honeycomb','one solid block with no pores','a perfectly flat metal surface'],'many small spaces like a honeycomb','cellular.s3 指具有许多小孔或小室的蜂窝状材料。'),q('cellular',4,1,'Which is a cellular structure in biology?',['a tissue made of many living cells','a single piece of pure glass','a radio tower'],'a tissue made of many living cells','生物学 cellular 指由细胞组成的组织。')]});
D('celluloid',{etymology:e('celluloid 是19世纪末注册并推广的材料名，由 cellulose 加 -oid“类似的”构成；早期塑料以硝化纤维素和樟脑制成，曾广泛用于电影胶片。','celluloid'),contexts:[c('celluloid.s2','电影史','The historian described the early silent era as celluloid at its most inventive, when filmmakers experimented with close-ups and rapid cuts.','历史学家把早期默片时代称作电影艺术最富创新的时期，当时电影人不断尝试特写和快速剪辑。','The historian described the early silent era as celluloid at its most inventive / when filmmakers experimented with close-ups and rapid cuts.','celluloid 以电影媒介转喻电影；when 从句补充该时期的创新实践。','谈电影艺术及电影制作，体现 celluloid.s2 的电影义。')],mistakes:[m('The archive stored nitrate celluloid film in a hot, damp room because the material was nonflammable and could not decay.','The archive stored nitrate celluloid film in a cool, controlled room because the material can be flammable and deteriorate.','硝化纤维素胶片可燃且会劣化；把材料说成绝不燃烧、不能变质不正确。')],quiz:[q('celluloid',1,1,'Celluloid was an early form of?',['plastic made from cellulose nitrate and camphor','natural stone used in bridge arches','a metal alloy for aircraft'],'plastic made from cellulose nitrate and camphor','celluloid.s1 指早期塑料赛璐珞。'),q('celluloid',2,2,'“The history of celluloid” may refer to the history of?',['cinema and motion-picture film','cellular blood vessels','religious teaching manuals'],'cinema and motion-picture film','celluloid.s2 可转指电影及电影胶片。'),q('celluloid',3,1,'Why were old celluloid film reels stored carefully?',['some nitrate film can be flammable and deteriorate','celluloid is edible and attracts insects','the reels are made of wet paper'],'some nitrate film can be flammable and deteriorate','早期硝化纤维素片基可能燃烧并随时间劣化。'),q('celluloid',4,2,'A critic writing “celluloid classics” is discussing?',['classic films','chemical catalysts','types of tree bark'],'classic films','celluloid 是电影的旧式转喻。')]});
D('cellulose',{etymology:e('cellulose 由 cell 加化学物质后缀 -ulose 构成；该名由 Anselme Payen 于19世纪提出，指植物细胞壁中的主要结构多糖。','cellulose'),contexts:[c('cellulose.s1','植物生物学','Ruminants digest cellulose with help from microbes in their gut, allowing them to obtain nutrients from grasses that humans cannot break down efficiently.','反刍动物借助肠道微生物消化纤维素，因此能从人类难以有效分解的草中获取营养。','Ruminants digest cellulose with help from microbes in their gut / allowing them to obtain nutrients from grasses / that humans cannot break down efficiently.','cellulose 是 digest 的宾语；that 从句修饰 grasses。','植物细胞壁多糖被反刍动物消化，体现纤维素义。')],mistakes:[m('Cellulose is the animal storage sugar found in muscle and is made chiefly of amino acids.','Glycogen is the animal storage carbohydrate found in muscle; cellulose is a plant cell-wall polysaccharide.','纤维素构成植物细胞壁，不是动物肌肉中的储存糖，也非氨基酸聚合物。')],quiz:[q('cellulose',1,1,'Cellulose is a structural material found mainly in?',['plant cell walls','animal muscle as a storage sugar','the outer shell of metal tools'],'plant cell walls','cellulose.s1 指植物细胞壁的主要结构多糖。'),q('cellulose',2,1,'Why can many humans not digest cellulose efficiently?',['they lack the enzymes needed to break its bonds','it is a type of iron','it dissolves immediately into protein'],'they lack the enzymes needed to break its bonds','人类不能有效分解纤维素中的特定键。'),q('cellulose',3,1,'A cotton fiber is rich in?',['cellulose','cathode material','caffeine'],'cellulose','棉纤维主要由纤维素构成。'),q('cellulose',4,1,'Which is not cellulose’s usual role?',['strengthening plant cell walls','providing structural support in plants','serving as the main storage sugar in animal muscle'],'serving as the main storage sugar in animal muscle','动物肌肉储存糖主要是糖原，不是纤维素。')]});
D('cementation',{etymology:e('cementation 由 cement 加 -ation 构成，源于拉丁语 caementum“碎石、砌筑材料”；地质学指颗粒被矿物胶结，冶金学另指表面渗碳等处理。','cementation'),contexts:[c('cementation.s1','沉积地质','Over millions of years, mineral-rich groundwater filled the gaps between sand grains, and cementation turned the loose deposit into sandstone.','数百万年间，富含矿物质的地下水填充了砂粒间隙，胶结作用把松散沉积物变成砂岩。','Over millions of years / mineral-rich groundwater filled the gaps between sand grains / and cementation turned the loose deposit into sandstone.','cementation 是 turned 的主语；and 连接过程与结果。','矿物在颗粒之间沉淀并将其黏结成岩石，符合地质义 s1。')],mistakes:[m('The sandstone remained loose because cementation dissolved every mineral bridge joining the sand grains.','The sandstone remained loose because cementation had not yet formed mineral bridges between the sand grains.','胶结作用形成矿物连接；若颗粒松散，应是胶结尚未发生而非它溶解所有连接。')],quiz:[q('cementation',1,1,'In sedimentary geology, cementation?',['binds sediment grains with minerals','turns a rock into a gas','sorts fossils by age'],'binds sediment grains with minerals','cementation.s1 指矿物胶结颗粒形成沉积岩。'),q('cementation',2,2,'In metallurgy, cementation may involve?',['altering a metal surface by adding an element such as carbon','pouring concrete over a road','classifying soil by color'],'altering a metal surface by adding an element such as carbon','s2 还可指使元素渗入金属表层的处理。'),q('cementation',3,1,'Loose sand becoming sandstone through mineral binding illustrates?',['cementation','censorship','cavorting'],'cementation','砂粒被矿物胶结成岩是地质胶结作用。'),q('cementation',4,1,'What can act as a natural cement between sediment grains?',['precipitated mineral matter','a spoken apology','an empty air gap'],'precipitated mineral matter','矿物沉淀可充当颗粒之间的天然胶结物。')]});
D('cenote',{etymology:e('cenote 经西班牙语 cenote 借自尤卡坦玛雅语 dzonot“井、深穴”；它是尤卡坦石灰岩地貌中通向地下水的天然塌陷坑。','cenote'),contexts:[c('cenote.s1','尤卡坦地貌','Divers entered the cenote through a limestone opening and followed its flooded cavern toward an underground river.','潜水员从石灰岩开口进入天然井，沿着被水淹没的洞穴前往地下河。','Divers entered the cenote through a limestone opening / and followed its flooded cavern / toward an underground river.','cenote 是 entered 的宾语；limestone opening 和地下水环境界定地貌。','石灰岩塌陷坑向地下水开放，是尤卡坦典型 cenote。')],mistakes:[m('The cenote was a man-made steel reservoir built above ground with no sinkhole or connection to groundwater.','The reservoir was a man-made steel tank built above ground with no sinkhole or connection to groundwater.','cenote 指天然石灰岩天坑/井，不能指地上人工钢罐。')],quiz:[q('cenote',1,1,'A cenote is typically a natural opening into?',['groundwater beneath limestone','a volcanic cloud above a crater','a dry desert dune'],'groundwater beneath limestone','cenote.s1 是通向地下水的天然坑穴。'),q('cenote',2,1,'Where are cenotes especially associated?',['the Yucatan Peninsula','the Arctic Ocean','the Alps of central Europe'],'the Yucatan Peninsula','尤卡坦石灰岩地貌以天然井著称。'),q('cenote',3,1,'Divers entering a cenote are likely to encounter?',['a flooded limestone cavern','a dry city tunnel','a mountain glacier'],'a flooded limestone cavern','天然井常连通被地下水淹没的洞穴。'),q('cenote',4,1,'Which formation best fits the word cenote?',['a natural sinkhole exposing groundwater','an artificial swimming pool on a roof','a dry pile of volcanic ash'],'a natural sinkhole exposing groundwater','天然塌陷坑及地下水是 cenote 的关键特征。')]});
D('cenozoic',{etymology:e('Cenozoic 由希腊语 kainos“新的、近来的”和 zōē“生命”构成；地质学家 John Phillips 于1840年提出该名称，用于中生代之后至今的地质时代。','cenozoic'),contexts:[c('cenozoic.s2','地质年代','Cenozoic sediments in the basin contain abundant mammal fossils, so researchers compared them with rocks from the same era elsewhere.','盆地的新生代沉积物含有大量哺乳动物化石，因此研究人员把它们与其他地区同一时代的岩石作了比较。','Cenozoic sediments in the basin contain abundant mammal fossils / so researchers compared them with rocks / from the same era elsewhere.','Cenozoic 修饰 sediments；same era 回指新生代。','描述属于该地质时代的岩石，使用形容词义 s2。')],mistakes:[m('The Cenozoic is the geological era before the dinosaurs, ending before the Mesozoic began.','The Cenozoic is the geological era after the Mesozoic, extending from about 66 million years ago to the present.','新生代位于中生代之后，而非恐龙时代之前。')],quiz:[q('cenozoic',1,1,'The Cenozoic is the geological era that?',['follows the Mesozoic and continues to the present','ended before the first dinosaurs appeared','comes before the Paleozoic'],'follows the Mesozoic and continues to the present','cenozoic.s1 指中生代之后直至现在的新生代。'),q('cenozoic',2,2,'A Cenozoic fossil is one found in rocks?',['belonging to that geological era','from the future','formed only in the Precambrian'],'belonging to that geological era','形容词义指属于新生代的岩石或化石。'),q('cenozoic',3,1,'The rise of mammals is strongly associated with the?',['Cenozoic','Bronze Age','Jurassic period alone'],'Cenozoic','哺乳动物在新生代成为优势类群。'),q('cenozoic',4,1,'The name Cenozoic combines Greek elements referring to?',['recent life','deep water','metal work'],'recent life','词名由“新的/近来的”与“生命”构成。')]});
D('censorship',{etymology:e('censorship 由 censor 加 -ship 构成；censor 源自拉丁语 censor，指古罗马负责审查人口、财产与公共行为的官员，后发展为对传播内容的审查。','censorship'),contexts:[c('censorship.s1','新闻出版','The new censorship rules required newspapers to submit articles for review before publication, and several reports were removed from the final edition.','新的审查规定要求报纸在出版前提交文章审核，最终版本中有几篇报道被删去。','The new censorship rules required newspapers to submit articles for review before publication / and several reports were removed from the final edition.','censorship 修饰 rules；before publication 表明审查发生在发布之前。','审查并压制被当局禁止的内容，符合 censorship。')],mistakes:[m('The country ended censorship by requiring every book to be approved and every critical article to be suppressed before publication.','The country tightened censorship by requiring every book to be approved and every critical article to be suppressed before publication.','强制审批并压制批评内容是加强审查，不是结束审查。')],quiz:[q('censorship',1,1,'Censorship is the practice of?',['reviewing and suppressing material an authority rejects','printing every submitted text unchanged','teaching students to write headlines'],'reviewing and suppressing material an authority rejects','censorship.s1 指审查并删除当局不允许发布的内容。'),q('censorship',2,1,'A censored newspaper article may have been?',['cut or blocked before publication','translated into a different font only','delivered without review'],'cut or blocked before publication','审查常导致文章被删改或禁止发布。'),q('censorship',3,1,'Which policy is an example of censorship?',['an authority bans a documentary it considers unacceptable','a library adds a new shelf label','a reporter corrects a misspelling'],'an authority bans a documentary it considers unacceptable','当局禁止其不认可的影片属于内容审查。'),q('censorship',4,1,'The Roman censor was connected with the word because the office involved?',['official oversight of public conduct and records','composing operas','building irrigation canals'],'official oversight of public conduct and records','现代 censor/censorship 与古罗马监察官相关。')]});
D('censure',{etymology:e('censure 经法语 censure 源自拉丁语 censura“审查、评定”，关联 censere“评估、判断”；古罗马 censor 的监察职权与其词源相关。','censure'),contexts:[c('censure.s2','议会程序','After investigators documented the conflict of interest, the assembly voted a formal censure against the member but did not remove her from office.','调查人员记录利益冲突后，议会投票正式谴责该成员，但没有将她免职。','After investigators documented the conflict of interest / the assembly voted a formal censure against the member / but did not remove her from office.','censure 是 voted 的宾语；but 区分谴责处分与免职。','议会作出的正式责备处分体现名词义 s2。')],mistakes:[m('The council praised the official with a censure, publicly celebrating his conduct as exemplary.','The council honored the official with an award, publicly celebrating his conduct as exemplary.','censure 表示强烈责备，不是表彰或奖励。')],quiz:[q('censure',1,1,'A censure expresses?',['strong disapproval or criticism','a certificate of outstanding praise','a neutral weather report'],'strong disapproval or criticism','censure.s1 指强烈批评、表示不赞同。'),q('censure',2,2,'A legislature’s formal censure is?',['an official vote of blame','an automatic criminal conviction','a promotion to higher office'],'an official vote of blame','议会 censure 是正式谴责处分，不等于定罪。'),q('censure',3,3,'If officials censure a company, they?',['express severe disapproval of it','give it a tax exemption as reward','publish its sales figures without comment'],'express severe disapproval of it','动词 censure 表示严厉谴责。'),q('censure',4,2,'Which action is a formal censure?',['a council votes to condemn a member’s misconduct','a council elects a new chair','a clerk records attendance'],'a council votes to condemn a member’s misconduct','投票正式责备不当行为体现议会名词义。')]});
D('centenary',{etymology:e('centenary 由拉丁语 centenarius“每百个、百年的”进入英语，词根 centum 意为“一百”；英式英语中常作百周年名词，也可作形容词。','centenary'),contexts:[c('centenary.s1','机构纪念','The museum marked the centenary of its opening with a public exhibition tracing a hundred years of local discoveries.','博物馆举办公众展览，纪念开馆一百周年，并回顾当地一百年来的发现。','The museum marked the centenary of its opening / with a public exhibition / tracing a hundred years of local discoveries.','centenary 是 marked 的宾语；of its opening 指被纪念事件。','开馆满一百周年，体现 s1 名词义。')],mistakes:[m('The club celebrated its centenary after only ten years of existence and called the event its hundredth anniversary.','The club celebrated its decennial after ten years of existence and called the event its tenth anniversary.','centenary 指一百周年；十周年应称 decennial 或 tenth anniversary。')],quiz:[q('centenary',1,1,'A centenary is the?',['hundredth anniversary of an event','tenth anniversary','weekly celebration'],'hundredth anniversary of an event','centenary.s1 指事件发生的一百周年。'),q('centenary',2,2,'A centenary exhibition is one?',['connected with a hundred-year anniversary','held every ten days','about a century of rainfall only'],'connected with a hundred-year anniversary','形容词义表示与百年纪念或百年时期相关。'),q('centenary',3,1,'A school founded in 1926 celebrates its centenary in?',['2026','1936','2126'],'2026','百年纪念在成立一百年后，即 2026 年。'),q('centenary',4,1,'The element cent- in centenary refers to?',['one hundred','one thousand','one quarter'],'one hundred','cent- 来自拉丁语 centum“一百”。')]});
D('centennial',{etymology:e('centennial 由拉丁语 centum“一百”与 annus“年”相关词素构成，19世纪英语中用于百年时期及其纪念；名词常指百年纪念庆典。','centennial'),contexts:[c('centennial.s2','大学校庆','The university’s centennial drew alumni back to campus for a ceremony, a history exhibit, and the dedication of a new research hall.','大学的百年庆典吸引校友重返校园，参加仪式、校史展览以及新研究楼的落成典礼。','The university’s centennial drew alumni back to campus / for a ceremony, a history exhibit, / and the dedication of a new research hall.','centennial 作 drew 的主语，名词义指百年纪念庆典。','百年校庆活动本身是 centennial.s2。')],mistakes:[m('The town held a centennial for the fifth anniversary of its founding, only five years after it was established.','The town held a centennial for the hundredth anniversary of its founding, a century after it was established.','centennial 的纪念节点是满一百年；五周年不是百年庆典。')],quiz:[q('centennial',1,1,'A centennial event marks?',['one hundred years','fifty days','ten centuries'],'one hundred years','centennial.s1 指与一百年有关。'),q('centennial',2,2,'A town’s centennial is its?',['celebration of its 100th anniversary','annual harvest every autumn','official count of its population'],'celebration of its 100th anniversary','centennial.s2 指百年周年庆典。'),q('centennial',3,1,'A centennial coin would most likely commemorate?',['a 100-year milestone','a person’s first birthday','a monthly election'],'a 100-year milestone','百年纪念币庆祝满一百年的节点。'),q('centennial',4,2,'“The centennial opened with a parade” uses centennial as a?',['noun for the anniversary celebration','verb meaning to count','preposition for location'],'noun for the anniversary celebration','parade 在百年庆典上举行，centennial 是名词。')]});
D('centipede',{etymology:e('centipede 经法语 centipède 来自拉丁语 centipeda，由 centum“一百”和 pes/pedis“脚”构成；名称不表示每种蜈蚣都恰有一百条腿。','centipede'),contexts:[c('centipede.s2','昆虫观察','The centipede bit the gardener’s glove, and its venomous bite caused sharp local pain even though the skin was not broken.','蜈蚣咬了园丁的手套；尽管皮肤没有破损，它带毒的咬伤仍造成了局部剧痛。','The centipede bit the gardener’s glove / and its venomous bite caused sharp local pain / even though the skin was not broken.','centipede 是 bit 的主语；venomous bite 对应带毒咬伤义。','有毒多足类动物的咬伤造成疼痛，体现 s2。')],mistakes:[m('The centipede was a harmless butterfly with six legs and colorful wings resting on a flower.','The butterfly was a harmless insect with six legs and colorful wings resting on a flower.','蜈蚣是多足类动物而非六足蝴蝶；描述的有翅昆虫应叫 butterfly。')],quiz:[q('centipede',1,1,'A centipede is a?',['long, flat-bodied animal with many pairs of legs','six-legged bird with feathers','plant with a hundred leaves'],'long, flat-bodied animal with many pairs of legs','centipede.s1 指身体扁长、具有许多对足的动物。'),q('centipede',2,2,'Why might someone avoid handling a centipede?',['some kinds have a painful venomous bite','it is a type of harmless paper','it has no legs or movement'],'some kinds have a painful venomous bite','centipede.s2 特别提示某些蜈蚣的毒咬伤。'),q('centipede',3,1,'Despite its name, a centipede?',['need not have exactly 100 legs','is a bird with 100 wings','always has exactly 50 pairs of legs'],'need not have exactly 100 legs','名称的拉丁构词不代表实际腿数固定为一百。'),q('centipede',4,2,'A painful bite from a venomous multi-legged animal may come from a?',['centipede','celery stalk','cello bow'],'centipede','带毒多足动物的咬伤符合 centipede.s2。')]});
D('centrality',{etymology:e('centrality 由 central 加名词后缀 -ity 构成；central 经拉丁语 centralis 与 centrum“中心”相关，指位置居中或重要性居核心。','centrality'),contexts:[c('centrality.s1','城市规划','The centrality of the railway station shaped the new bus routes, because most neighborhoods needed a direct connection to that hub.','火车站的中心地位影响了新的公交线路规划，因为大多数社区都需要直达这一枢纽。','The centrality of the railway station shaped the new bus routes / because most neighborhoods needed a direct connection / to that hub.','centrality 是 shaped 的主语；because 说明车站为何重要。','车站在交通网络中的枢纽位置和重要性均体现中心地位。')],mistakes:[m('The centrality of the remote outpost meant it was unimportant, isolated, and unrelated to every major route.','The remoteness of the outpost meant it was unimportant, isolated, and unrelated to every major route.','与主要路线无关且偏远的地点没有中心地位，原句自相矛盾。')],quiz:[q('centrality',1,1,'The centrality of a station can refer to its?',['key position or importance in a network','lack of any connection to other routes','exact color on a map'],'key position or importance in a network','centrality.s1 指位置或重要性上的核心地位。'),q('centrality',2,1,'If a concept has centrality in a theory, it is?',['fundamental to the theory','irrelevant to every argument','a footnote’s page number'],'fundamental to the theory','概念的 centrality 表示其在理论中居于核心。'),q('centrality',3,1,'Which phrase expresses centrality?',['the hub is crucial to the entire transport system','the side road is disconnected from all routes','the station is painted red'],'the hub is crucial to the entire transport system','枢纽对整个交通系统关键，体现核心重要性。'),q('centrality',4,1,'Centrality names the quality of being?',['central in position or importance','careful about danger','able to conduct electricity'],'central in position or importance','centrality 表示处于中心或占据重要位置的性质。')]});
D('centralization',{etymology:e('centralization 由 centralize 加名词后缀 -ation 构成；central 来自拉丁语 centrum“中心”，该词指权力、决定或服务向单一中心汇集的过程。','centralization'),contexts:[c('centralization.s1','公共行政','Centralization gave the national ministry control over school budgets, while local principals lost the authority to move funds between programs.','权力集中使国家部委掌控学校预算，而地方校长失去了在项目间调拨资金的权力。','Centralization gave the national ministry control over school budgets / while local principals lost the authority / to move funds between programs.','centralization 是主语；while 对比控制权集中前后的权限变化。','预算决定权转至国家部委，体现集中化过程。')],mistakes:[m('The reform achieved centralization by giving every village complete authority to make local decisions without national oversight.','The reform achieved decentralization by giving every village complete authority to make local decisions without national oversight.','决策权下放到各村属于分权，不是向单一中心集中。')],quiz:[q('centralization',1,1,'Centralization of government means?',['bringing decision-making under a central authority','dividing authority among independent local offices','removing all forms of administration'],'bringing decision-making under a central authority','centralization.s1 指权力或决策集中到单一中心。'),q('centralization',2,1,'A centralized budget system is created through?',['the transfer of budget control to one central office','giving every branch an independent budget','letting no one allocate money'],'the transfer of budget control to one central office','预算权向中央办公室集中，体现 centralization。'),q('centralization',3,1,'Which is an example of centralization?',['one ministry approves all regional spending','each town sets policy without a national body','offices stop recording decisions'],'one ministry approves all regional spending','各地支出由单一部委批准属于权力集中。'),q('centralization',4,1,'Centralization names a?',['process of concentrating control or services','person who runs a school','chemical reaction at an electrode'],'process of concentrating control or services','-ization 构成过程名词，centralization 即集中化过程。')]});
D('centralize',{etymology:e('centralize 由 central 加动词后缀 -ize 构成，central 经拉丁语 centralis 来自 centrum“中心”；及物义使权力归于中心，不及物义指权力汇集。','centralize'),contexts:[c('centralize.s2','组织改革','As the separate departments merged, purchasing began to centralize under one office, which negotiated prices for the whole organization.','各部门合并后，采购工作开始集中到一个办公室，由该办公室为整个机构议价。','As the separate departments merged / purchasing began to centralize under one office / which negotiated prices for the whole organization.','centralize 作不及物动词；under one office 表明权力汇集的中心。','采购权自行向一个主管办公室汇聚，对应 s2。')],mistakes:[m('The board chose to centralize purchasing by assigning every branch a separate buyer with full independent authority.','The board chose to decentralize purchasing by assigning every branch a separate buyer with full independent authority.','每个分支独立决定采购属于分权；centralize 意味着交由中心统筹。')],quiz:[q('centralize',1,1,'To centralize control is to?',['bring it under one central authority','give every office complete independence','abolish all decisions'],'bring it under one central authority','centralize.s1 是把控制权集中到一个中心。'),q('centralize',2,2,'If decision-making begins to centralize, it?',['comes together under a central authority','spreads to every local group','stops being possible'],'comes together under a central authority','不及物用法指权力向中央集中。'),q('centralize',3,1,'A company centralizes payroll when it?',['moves payroll decisions to headquarters','lets every store use unrelated pay rules','stops paying employees'],'moves payroll decisions to headquarters','把工资管理交给总部就是集中管理。'),q('centralize',4,2,'In “authority began to centralize,” centralize is used?',['without a direct object','with a person as its only object','as an adjective before a noun'],'without a direct object','该句中 centralize 表示权力自行汇集，作不及物动词。')]});
D('centralized',{etymology:e('centralized 是 centralize 的过去分词形容词；centralize 以 central 加 -ize 构成，形容由一个中心机构而非多个地方单位控制。','centralized'),contexts:[c('centralized.s1','公司治理','In the centralized company, headquarters approved every large purchase, leaving regional managers to implement decisions rather than set policy.','在这家集权管理的公司里，每笔大额采购都由总部批准，地区经理只能执行决定而不能制定政策。','In the centralized company / headquarters approved every large purchase / leaving regional managers to implement decisions rather than set policy.','centralized 修饰 company；headquarters 对各地区决策统一审批。','主要决定由总部作出，说明其管理结构是集中的。')],mistakes:[m('The organization was centralized because each local branch made all its own policies without reporting to headquarters.','The organization was decentralized because each local branch made all its own policies without reporting to headquarters.','地方各自独立制定政策说明权力分散，与 centralized 相反。')],quiz:[q('centralized',1,1,'A centralized organization has its main decisions made?',['by one central authority','independently by every local office','by no person or group'],'by one central authority','centralized.s1 指由单一中心控制、作主要决定。'),q('centralized',2,1,'Which workplace is centralized?',['headquarters approves every branch’s major spending','each branch sets all policy by itself','branches have no shared reporting system'],'headquarters approves every branch’s major spending','总部统一审批各分部支出，体现集中管理。'),q('centralized',3,1,'A centralized service is likely coordinated?',['from one central office','separately by unrelated local units','only by customers'],'from one central office','中心办公室统一协调服务，符合 centralized。'),q('centralized',4,1,'The clearest opposite of centralized is?',['decentralized','cerebral','ceremonious'],'decentralized','decentralized 表示分散管理，与 centralized 相对。')]});
D('centrally',{etymology:e('centrally 是 central 加副词后缀 -ly 构成；central 经拉丁语 centralis 与 centrum“中心”相连，副词可指地点居中或由中央机构管理。','centrally'),contexts:[c('centrally.s1','交通位置','The clinic is centrally located between the railway station and the bus terminal, so patients can reach it from either side of town.','诊所位于市中心，在火车站和公交总站之间，因此镇上两边的患者都容易到达。','The clinic is centrally located between the railway station and the bus terminal / so patients can reach it / from either side of town.','centrally 修饰 located；between 说明其居中的地理位置。','诊所在两个交通枢纽之间、便于两边到达，体现地点居中义。')],mistakes:[m('The centrally located clinic stood beyond every town boundary, far from the center and unreachable by local transport.','The remotely located clinic stood beyond every town boundary, far from the center and unreachable by local transport.','远离中心且边界之外的位置不应称 centrally located。')],quiz:[q('centrally',1,1,'A centrally located hotel is?',['in or near the center','far outside the city','inside a private vehicle'],'in or near the center','centrally.s1 指位于中心或靠近中心。'),q('centrally',2,1,'A service managed centrally is controlled?',['from a central authority','independently by every neighborhood','by no administrator'],'from a central authority','centrally 也可表示由中央机构管理。'),q('centrally',3,1,'Which location is most likely centrally placed?',['a station at the hub of a town’s main routes','a cabin far beyond the last road','a boat in the open sea'],'a station at the hub of a town’s main routes','主要线路枢纽处的位置居中。'),q('centrally',4,1,'In “the budget is centrally controlled,” centrally modifies?',['the way control is organized','the color of the budget','the number of pages'],'the way control is organized','centrally 修饰 controlled，说明控制来自中央。')]});
D('centric',{etymology:e('centric 经拉丁语 centricus 源自希腊语 kentron“圆规尖端、中心”；现代常见于 ethnocentric、geocentric 等复合形容词，表示以所指对象为中心。','centric'),contexts:[c('centric.s1','产品设计','The redesign is user-centric: the team observed how older customers navigate the app before deciding where to place each control.','这次改版以用户为中心：团队先观察年长顾客如何使用应用，再决定每个控件的位置。','The redesign is user-centric / the team observed how older customers navigate the app / before deciding where to place each control.','centric 与 user 构成复合形容词；冒号解释设计如何围绕用户展开。','设计把用户需求当作中心，体现以……为中心义。')],mistakes:[m('A geocentric model places the Sun at the center and treats Earth as irrelevant to the system.','A heliocentric model places the Sun at the center; a geocentric model places Earth there.','geocentric 表示以地球为中心；把太阳置于中心应称 heliocentric。')],quiz:[q('centric',1,1,'A user-centric design puts?',['users’ needs at the center','the designer’s lunch at the center','no one’s needs into consideration'],'users’ needs at the center','centric.s1 表示以所提对象为中心。'),q('centric',2,1,'A geocentric account is organized around?',['Earth','the Moon only','a city’s central station'],'Earth','geo- 指地球；geocentric 即以地球为中心。'),q('centric',3,1,'Which phrase describes an approach focused on data?',['data-centric method','data-free method','ceremonious method'],'data-centric method','data-centric 表示以数据为中心或重点。'),q('centric',4,1,'The element -centric most nearly signals?',['centered on or focused around something','without any relation to a center','happening once every hundred years'],'centered on or focused around something','-centric 构成以某对象为中心的形容词。')]});
D('cerebellum',{etymology:e('cerebellum 是拉丁语 cerebrum“脑”加指“小”的 -ellum 构成，字面为“小脑”；该脑区负责协调运动、姿势和身体平衡。','cerebellum'),contexts:[c('cerebellum.s1','神经科学','After the injury damaged his cerebellum, the patient could still understand instructions but struggled to coordinate his steps and maintain balance.','小脑受伤后，患者仍能理解指令，却难以协调步伐并保持平衡。','After the injury damaged his cerebellum / the patient could still understand instructions / but struggled to coordinate his steps and maintain balance.','cerebellum 是 damaged 的宾语；but 对比理解能力与运动协调受损。','平衡与动作协调障碍指向小脑功能。')],mistakes:[m('The cerebellum primarily controls complex language reasoning, while the spinal cord alone coordinates balance and movement.','The cerebrum is strongly involved in language and reasoning, while the cerebellum coordinates movement and balance.','把大脑的高级认知功能归给小脑混淆了脑区。')],quiz:[q('cerebellum',1,1,'The cerebellum helps coordinate?',['movement and balance','digestion in the stomach','the beating of the heart only'],'movement and balance','cerebellum.s1 的核心功能是协调运动与平衡。'),q('cerebellum',2,1,'Damage to the cerebellum may make a person?',['unsteady and poorly coordinated','unable to digest cellulose only','blind in every case'],'unsteady and poorly coordinated','小脑受损常影响协调动作和保持平衡。'),q('cerebellum',3,1,'Where is the cerebellum located?',['at the back of the brain','inside the knee joint','in the center of the spinal disc'],'at the back of the brain','小脑位于脑后部。'),q('cerebellum',4,1,'The Latin form behind cerebellum literally suggests?',['a little brain','a hundred feet','a central authority'],'a little brain','cerebellum 是表示“小脑”的拉丁构词。')]});
D('cerebrospinal',{etymology:e('cerebrospinal 由 cerebro-“脑”与 spinal“脊髓的”组合而成；cerebro- 源于拉丁语 cerebrum“脑”，术语指同时关联脑与脊髓。','cerebrospinal'),contexts:[c('cerebrospinal.s1','临床检验','The laboratory analyzed cerebrospinal fluid from the patient’s lower back to look for signs of infection around the brain and spinal cord.','实验室分析了从患者下背部取得的脑脊液，以寻找脑和脊髓周围感染的迹象。','The laboratory analyzed cerebrospinal fluid / from the patient’s lower back / to look for signs of infection around the brain and spinal cord.','cerebrospinal 修饰 fluid；to look for 表示检验目的。','脑脊液关联脑与脊髓，直接体现词义。')],mistakes:[m('A cerebrospinal sample came only from the liver and had no connection to either the brain or spinal cord.','A hepatic sample came only from the liver and had no connection to the brain or spinal cord.','只与肝脏有关的是 hepatic；cerebrospinal 同时关联脑和脊髓。')],quiz:[q('cerebrospinal',1,1,'Cerebrospinal refers to the?',['brain and spinal cord together','heart and lungs together','bones of the hand'],'brain and spinal cord together','cerebrospinal.s1 由脑与脊髓两部分构成。'),q('cerebrospinal',2,1,'Cerebrospinal fluid circulates around?',['the brain and spinal cord','the stomach and liver','the outer surface of a fingernail'],'the brain and spinal cord','脑脊液围绕中枢神经系统。'),q('cerebrospinal',3,1,'A cerebrospinal examination might help investigate?',['an infection near the central nervous system','a broken shoe buckle','a plant’s root growth'],'an infection near the central nervous system','脑脊液检验可协助检查脑和脊髓相关疾病。'),q('cerebrospinal',4,1,'Which parts form the compound cerebrospinal?',['cerebro- (brain) and spinal','cello and central','censor and spinal cord only'],'cerebro- (brain) and spinal','该复合词由“脑”与“脊髓的”组合。')]});
D('cerebrum',{etymology:e('cerebrum 是拉丁语“脑”的名称，进入解剖学英语后特指脑的最大部分，分为左右两半球，参与感觉、语言、思维和随意运动。','cerebrum'),contexts:[c('cerebrum.s1','脑解剖','The MRI showed a lesion in the cerebrum, the large upper part of the brain involved in conscious thought and voluntary movement.','核磁共振显示大脑出现病灶；大脑是参与意识思维和随意运动的脑部较大上半部分。','The MRI showed a lesion in the cerebrum / the large upper part of the brain / involved in conscious thought and voluntary movement.','cerebrum 是介词 in 的宾语；同位语说明其位置和功能。','意识思维与随意动作所在的大脑主体是 cerebrum。')],mistakes:[m('The cerebrum is the small hindbrain structure chiefly responsible for balance and coordinating each muscle movement.','The cerebellum is the hindbrain structure chiefly responsible for balance and coordinating movement.','平衡和动作协调主要由 cerebellum（小脑）承担，不是 cerebrum。')],quiz:[q('cerebrum',1,1,'The cerebrum is?',['the large upper part of the brain','a bone in the inner ear','a muscle in the leg'],'the large upper part of the brain','cerebrum.s1 指脑的最大上部区域。'),q('cerebrum',2,1,'The cerebrum is strongly involved in?',['thought and voluntary action','balancing a bicycle alone','producing digestive enzymes'],'thought and voluntary action','大脑参与思维与随意运动。'),q('cerebrum',3,1,'The cerebrum is divided into two major?',['hemispheres','stomachs','valves'],'hemispheres','大脑分为左右两个半球。'),q('cerebrum',4,1,'Which structure is more closely associated with balance coordination?',['cerebellum','cerebrum','cathode'],'cerebellum','小脑比大脑更直接负责平衡和动作协调。')]});
D('ceremonious',{etymology:e('ceremonious 由 ceremony 加 -ous 构成；ceremony 经法语与拉丁语 caerimonia“宗教仪式、敬礼”而来，可指仪式隆重或行为拘于礼节。','ceremonious'),contexts:[c('ceremonious.s2','社交礼仪','Their ceremonious greeting included three bows and a formal exchange of titles, although the two colleagues had worked together for years.','他们的问候十分讲究礼节，包括三次鞠躬和正式互称头衔，尽管两位同事已经共事多年。','Their ceremonious greeting included three bows and a formal exchange of titles / although the two colleagues had worked together for years.','ceremonious 修饰 greeting；although 对比正式礼数与彼此熟悉。','仔细、正式且略显拘谨的问候对应 s2。')],mistakes:[m('The ceremonious procession consisted of an unplanned private jog with no formal steps, guests, or ritual.','The informal procession consisted of an unplanned private jog with no formal steps, guests, or ritual.','没有仪式或正式礼节的随意慢跑不宜称 ceremonious。')],quiz:[q('ceremonious',1,1,'A ceremonious state opening is?',['conducted with grand formal ceremony','performed casually with no ritual','a chemical experiment'],'conducted with grand formal ceremony','ceremonious.s1 指仪式盛大而正式。'),q('ceremonious',2,2,'A ceremonious greeting may seem?',['very formal and carefully polite','rude and deliberately insulting','silent because no one is present'],'very formal and carefully polite','s2 描述讲究礼貌、形式较多的行为。'),q('ceremonious',3,1,'Which occasion is most likely ceremonious?',['a formal inauguration with prescribed rituals','a spontaneous chat at a bus stop','a quick text with no greeting'],'a formal inauguration with prescribed rituals','有规定仪式的就职典礼体现隆重正式。'),q('ceremonious',4,2,'The visitors exchanged ceremonious bows, suggesting?',['careful, formal politeness','a playful race','a hostile argument'],'careful, formal politeness','正式地互相鞠躬体现拘谨礼貌。')]});
D('certitude',{etymology:e('certitude 经法语 certitude 源自拉丁语 certitudo，与 certus“确定的”相关；指对某事确信无疑的状态或信心。','certitude'),contexts:[c('certitude.s1','科学论证','The data did not justify the researcher’s certitude, because the sample was small and two independent teams had failed to reproduce the result.','这些数据不足以支撑研究人员的确信，因为样本很小，而且两个独立团队都未能复现结果。','The data did not justify the researcher’s certitude / because the sample was small / and two independent teams had failed to reproduce the result.','certitude 是 justify 的宾语；because 说明不应如此确信的依据。','确信强度受到证据是否充分的检验，体现 certitude。')],mistakes:[m('She spoke with certitude that the result was certainly true, while insisting she had no confidence and was completely unsure.','She spoke with uncertainty about the result, insisting she had no confidence and was completely unsure.','完全不确定与 certitude（确信无疑）含义相反。')],quiz:[q('certitude',1,1,'Certitude is a state of?',['complete confidence or certainty','mild physical discomfort','formal public punishment'],'complete confidence or certainty','certitude.s1 指确信、确定的状态。'),q('certitude',2,1,'A witness speaking with certitude sounds?',['absolutely sure of the claim','unable to form any view','certain that every answer is unknown'],'absolutely sure of the claim','以 certitude 说话表示对陈述十分确定。'),q('certitude',3,1,'Which phrase is closest to certitude?',['certainty without doubt','a tentative guess','a change of address'],'certainty without doubt','certitude 与 certainty 意思最接近。'),q('certitude',4,1,'Weak evidence should usually reduce a researcher’s?',['certitude','cello','censorship'],'certitude','证据薄弱时应降低确信程度。')]});
D('cervical',{etymology:e('cervical 由拉丁语 cervicalis“颈部的”构成，源自 cervix“颈”；解剖学中 cervix 也指器官的狭窄颈部，因此 cervical 还可指子宫颈。','cervical'),contexts:[c('cervical.s2','妇科检查','The screening test checks for abnormal cells in the cervical tissue around the opening of the uterus.','这项筛查检查子宫开口周围的宫颈组织是否有异常细胞。','The screening test checks for abnormal cells / in the cervical tissue / around the opening of the uterus.','cervical 修饰 tissue；around 短语定位子宫颈所在部位。','子宫开口处的组织体现子宫颈义 s2。')],mistakes:[m('The cervical smear examined cells from the woman’s neck muscles rather than tissue at the opening of the uterus.','The cervical smear examined cells from tissue at the opening of the uterus rather than the neck muscles.','cervical 可有颈部与子宫颈两义；宫颈涂片取样部位不是颈肌。')],quiz:[q('cervical',1,1,'A cervical vertebra is located in the?',['neck','ankle','wrist'],'neck','cervical.s1 指颈部的，颈椎位于颈部。'),q('cervical',2,2,'A cervical screening sample concerns tissue of the?',['uterine cervix','elbow joint','outer ear'],'uterine cervix','cervical.s2 指子宫颈的。'),q('cervical',3,1,'A patient with cervical stiffness after a long flight has stiffness in the?',['neck','abdomen','toes'],'neck','颈部僵硬对应 cervical 的颈部义。'),q('cervical',4,2,'Which condition is cervical in the gynecological sense?',['abnormal cells in the uterine cervix','a strained calf muscle','a fractured finger'],'abnormal cells in the uterine cervix','妇科语境的 cervical 指子宫颈。')]});
D('cessation',{etymology:e('cessation 由 cease 的词干加名词后缀 -ation 构成；cease 经古法语 cessier 源自拉丁语 cessare“停止、休止”，cessation 即活动的停止或中止。','cessation'),contexts:[c('cessation.s1','消防安全','The factory ordered a cessation of welding until inspectors had repaired the damaged gas line and cleared the workshop.','工厂下令停止焊接，直到检查人员修好受损燃气管线并确认车间安全。','The factory ordered a cessation of welding / until inspectors had repaired the damaged gas line / and cleared the workshop.','cessation 是 ordered 的宾语；until 从句说明停止持续到何时。','焊接活动暂时中止，符合停止义。')],mistakes:[m('The cessation of the alarm meant that it continued ringing at the same volume all night.','The continuation of the alarm meant that it continued ringing at the same volume all night.','警报整夜持续响表示没有停止，不能称 cessation。')],quiz:[q('cessation',1,1,'A cessation of hostilities is?',['a stop or end to fighting','an increase in weapons production','a formal start to a battle'],'a stop or end to fighting','cessation.s1 指活动停止或结束。'),q('cessation',2,1,'The cessation of a service means the service?',['has stopped operating','has expanded its hours','has moved to a new building'],'has stopped operating','服务停止即发生 cessation。'),q('cessation',3,1,'Which phrase uses cessation correctly?',['the cessation of payments','the cessation of an ongoing payment that never stopped','the cessation of starting a new activity'],'the cessation of payments','payments 结束或停止可以称为 cessation。'),q('cessation',4,1,'Cessation is closest to?',['cessation','continuation','commencement'],'cessation','cessation 是停止；其反义概念包括 continuation 或 commencement。')]});
D('cession',{etymology:e('cession 经法语 cession 源自拉丁语 cessio“让出、转让”，来自 cedere“离开、让步”；法律和外交语境中特指正式让出领土、财产或权利。','cession'),contexts:[c('cession.s1','国际条约','The treaty required the cession of the border district to the neighboring state, with compensation paid to residents who chose to relocate.','条约要求把边境地区割让给邻国，并向选择迁居的居民支付补偿。','The treaty required the cession of the border district to the neighboring state / with compensation paid to residents / who chose to relocate.','cession 是 required 的宾语；of 短语指明转让对象。','通过条约正式转让领土体现 cession。')],mistakes:[m('The cession kept the province under its original government and transferred no land or rights to anyone.','The retention kept the province under its original government and transferred no land or rights to anyone.','没有转让领土或权利是保留，不是 cession。')],quiz:[q('cession',1,1,'A cession of territory is a formal?',['giving up or transferring of land','purchase of a new building','temporary border inspection'],'giving up or transferring of land','cession.s1 指领土的正式割让或转让。'),q('cession',2,1,'A legal cession of rights means the rights are?',['surrendered or transferred to another party','kept unchanged by the original holder','created by a spelling rule'],'surrendered or transferred to another party','cession 也可指权利正式转让。'),q('cession',3,1,'Which document might require a cession?',['a treaty transferring a border region','a restaurant menu','a weather forecast'],'a treaty transferring a border region','国家间条约可规定领土割让。'),q('cession',4,1,'Cession comes from a Latin word connected with?',['yielding or giving way','growing leaves','singing in a choir'],'yielding or giving way','拉丁词源 cedere 带有离开、让步的意义。')]});
D('chagrin',{etymology:e('chagrin 经法语 chagrin“忧恼、烦恼”进入英语；该法语词的更早词源有争议，因此不宜把它硬拆成未经证实的词根。','chagrin'),contexts:[c('chagrin.s2','竞赛结果','To her chagrin, the runner discovered that she had trained for months for a race postponed until the following spring.','令她懊恼的是，这位跑者发现自己训练数月的比赛被推迟到了来年春天。','To her chagrin / the runner discovered / that she had trained for months for a race postponed until the following spring.','to her chagrin 作句首评注短语；that 从句交代懊恼的原因。','计划落空带来失望与自尊受挫，符合动词义 s2 的致使情感。')],mistakes:[m('The cancellation delighted him to his chagrin, leaving him pleased rather than disappointed or embarrassed.','The cancellation annoyed him to his chagrin, leaving him disappointed and embarrassed.','to his chagrin 表示令他懊恼；delighted 却表示欣喜，情绪互相矛盾。')],quiz:[q('chagrin',1,1,'A feeling of chagrin combines disappointment with?',['embarrassment or wounded pride','physical hunger','complete indifference'],'embarrassment or wounded pride','chagrin.s1 是失望并伴随自尊受挫的懊恼。'),q('chagrin',2,2,'If a delay chagrins the passengers, it?',['makes them feel vexed or embarrassed','gives them a prize','makes the train run faster'],'makes them feel vexed or embarrassed','动词 chagrin 表示使某人懊恼。'),q('chagrin',3,1,'“To my chagrin, I had forgotten the tickets” signals?',['my annoyance and embarrassment','my relief and delight','my lack of any reaction'],'my annoyance and embarrassment','忘票造成的懊恼和尴尬符合名词义。'),q('chagrin',4,2,'Which sentence uses chagrin as a verb?',['The defeat chagrined the defending champion.','Her chagrin lasted all week.','The chagrin was recorded in the report.'],'The defeat chagrined the defending champion.','chagrined 是动词形式，意为使卫冕冠军懊恼。')]});
D('chairperson',{etymology:e('chairperson 由 chair（会议主席）与 person 组合而成，20世纪后期广泛用于不预设性别的职务称呼；chair 的主持义来自主持人坐席的转喻。','chairperson'),contexts:[c('chairperson.s1','会议主持','The chairperson kept the discussion on schedule, invited quieter members to speak, and summarized the committee’s decision at the end.','主席让讨论按时进行，邀请较少发言的成员表达意见，并在最后总结了委员会的决定。','The chairperson kept the discussion on schedule / invited quieter members to speak / and summarized the committee’s decision at the end.','chairperson 是并列谓语的主语；三项动作体现主持会议的职责。','主持委员会会议、组织发言的人即 chairperson。')],mistakes:[m('The chairperson was the person who attended the meeting only to take notes and had no role in presiding over it.','The secretary was the person who attended the meeting only to take notes and had no role in presiding over it.','只负责记录而不主持的人通常是 secretary，不是 chairperson。')],quiz:[q('chairperson',1,1,'A committee chairperson mainly?',['presides over meetings and guides discussion','serves every meal to the committee','repairs the meeting room'],'presides over meetings and guides discussion','chairperson.s1 指主持会议或组织机构的人。'),q('chairperson',2,1,'Why is chairperson often used instead of chairman?',['it does not specify the officeholder’s sex','it means the officeholder is always a woman','it names the room’s furniture'],'it does not specify the officeholder’s sex','chairperson 是性别中立的职务称呼。'),q('chairperson',3,1,'Who is most likely to call the meeting to order?',['the chairperson','a visitor with no assigned role','the caterer'],'the chairperson','会议主持人负责宣布会议开始并引导议程。'),q('chairperson',4,1,'A chairperson of a board is?',['the person who presides over it','a chair reserved for guests','the board’s youngest member by definition'],'the person who presides over it','chairperson 是主持董事会或委员会的人。')]});
D('chairwoman',{etymology:e('chairwoman 由 chair（会议主席）和 woman 构成，按职务加性别词素形成；chair 的主持义来自会议主持人坐在首席座位的转喻。','chairwoman'),contexts:[c('chairwoman.s1','董事会','The chairwoman opened the board meeting, called for a vote on the budget, and announced the result after each director had spoken.','女主席宣布董事会开会，提请对预算投票，并在每位董事发言后公布结果。','The chairwoman opened the board meeting / called for a vote on the budget / and announced the result / after each director had spoken.','chairwoman 是并列动作的主语；投票和宣布结果体现主持职责。','担任会议主席的女性对应 chairwoman.s1。')],mistakes:[m('The chairwoman chaired the meeting, but the term means that she was a man who led the committee.','The chairwoman chaired the meeting, and the term means that she was a woman who led the committee.','chairwoman 明确指担任主席的女性，不能解释为男性。')],quiz:[q('chairwoman',1,1,'A chairwoman is?',['a woman who presides over a meeting or organization','a woman who only owns a chair','a male member of the committee'],'a woman who presides over a meeting or organization','chairwoman.s1 指女性主席或主持人。'),q('chairwoman',2,1,'If the chairwoman calls for a vote, she is?',['presiding over the committee’s business','serving as the committee’s caterer','recording the weather'],'presiding over the committee’s business','召集投票是主持会议的职责。'),q('chairwoman',3,1,'Which title specifically identifies a female chair?',['chairwoman','chairperson, which is gender-neutral','treasurer'],'chairwoman','chairwoman 特指女性主席；chairperson 不标明性别。'),q('chairwoman',4,1,'The chairwoman announced the board’s decision. Her role was?',['leading or presiding over the board','auditing a restaurant kitchen','choosing the office furniture'],'leading or presiding over the board','董事会主席负责主持并公布决定。')]});
D('chalky',{etymology:e('chalky 由 chalk 加形容词后缀 -y 构成；chalk 经古英语 cealc 源自拉丁语 calx“石灰”，chalky 可指含白垩或像白垩般干白粉状。','chalky'),contexts:[c('chalky.s1','土壤与地质','The chalky soil drained quickly and left a pale powder on the gardener’s boots after a dry week.','白垩质土壤排水很快；干燥一周后，园丁的靴子上沾了一层浅色粉末。','The chalky soil drained quickly / and left a pale powder on the gardener’s boots / after a dry week.','chalky 修饰 soil；浅色粉末和排水性提供土壤含白垩的线索。','含白垩的土壤及其粉白特征体现 chalky.s1。')],mistakes:[m('The chalky paint looked clear, glossy, and oily, leaving no pale or powdery surface when dry.','The glossy paint looked clear and oily, leaving no pale or powdery surface when dry.','干后透明油亮而无粉感的漆不符合 chalky 的粉白质感。')],quiz:[q('chalky',1,1,'A chalky surface is often?',['white, dry, and powdery','transparent and oily','soft and liquid'],'white, dry, and powdery','chalky.s1 可描述白垩般灰白、干燥和粉状。'),q('chalky',2,1,'A chalky soil is likely to contain?',['chalk or limestone material','pure rubber','freshwater algae only'],'chalk or limestone material','chalky 可表示含白垩或石灰质。'),q('chalky',3,1,'Which wall finish is chalky?',['a pale surface that rubs off as powder','a clear glass panel','a wet polished steel plate'],'a pale surface that rubs off as powder','浅白、容易沾粉的墙面最符合该词。'),q('chalky',4,1,'The suffix -y in chalky makes an adjective meaning?',['having or resembling chalk','the act of measuring chalk','without any chalk-like quality'],'having or resembling chalk','-y 常表示“有……特征的”或“像……的”。')]});
D('challenger',{etymology:e('challenger 是 challenge 加施事后缀 -er 构成；challenge 经古法语 chalenge 源自拉丁语 calumnia“指控、争议”，后发展为提出竞争或质疑者。','challenger'),contexts:[c('challenger.s1','拳击赛事','The challenger studied the champion’s previous bouts, then entered the ring determined to dispute the title in a fair contest.','挑战者研究了冠军以往的比赛，然后走进拳台，决心在公平较量中争夺头衔。','The challenger studied the champion’s previous bouts / then entered the ring / determined to dispute the title in a fair contest.','challenger 是 studied 的主语；title 表明其挑战现任冠军。','与现任头衔持有者竞争的人是 challenger。')],mistakes:[m('The challenger accepted the championship without competing and was therefore the undisputed defending champion.','The champion accepted the title without competing and was therefore the defending champion.','挑战者是争夺头衔的一方；已持有并卫冕头衔者是 champion。')],quiz:[q('challenger',1,1,'A challenger in a title match is the person who?',['competes against the current title holder','already holds the title and faces no opponent','judges the contest from the sidelines'],'competes against the current title holder','challenger.s1 指挑战现任冠军或领头者的竞争者。'),q('challenger',2,1,'A challenger to a widely accepted idea is someone who?',['disputes or questions it','repeats it without comment','prints it in a larger font'],'disputes or questions it','challenger 也可以是质疑公认观点的人。'),q('challenger',3,1,'In a tournament, the challenger usually hopes to?',['defeat the reigning champion','award the champion a medal','cancel every match'],'defeat the reigning champion','挑战者进入比赛是为了争夺冠军头衔。'),q('challenger',4,1,'The suffix -er in challenger identifies?',['a person who performs the challenging','a past event only','a place where a game is played'],'a person who performs the challenging','-er 构成从事挑战行为的人。')]});
D('challenging',{etymology:e('challenging 是 challenge 加 -ing 构成的形容词；challenge 经古法语 chalenge 源自拉丁语 calumnia，形容考验能力的困难任务，也可指带质疑或挑衅意味的神情语气。','challenging'),contexts:[c('challenging.s2','争论语气','The reporter gave the minister a challenging look when he repeated a claim that the published figures had already disproved.','部长重提一个已被公开数据推翻的说法时，记者向他投去质疑的目光。','The reporter gave the minister a challenging look / when he repeated a claim / that the published figures had already disproved.','challenging 修饰 look；when 从句交代质疑目光出现的原因。','目光表达怀疑并邀请对方回应，符合 s2。')],mistakes:[m('The challenging exam was so effortless that every candidate finished it without using any skill or thought.','The simple exam was so effortless that every candidate finished it without using any skill or thought.','不费力且无需技能的考试不是考验能力的 challenging exam。')],quiz:[q('challenging',1,1,'A challenging assignment is?',['difficult in a way that tests ability','effortless and requiring no thought','a reward for finishing early'],'difficult in a way that tests ability','challenging.s1 指有一定难度、考验能力。'),q('challenging',2,2,'A challenging look may communicate?',['doubt or an invitation to defend a claim','sleepiness with no response','agreement without question'],'doubt or an invitation to defend a claim','challenging.s2 描写质疑或挑衅的目光、语气。'),q('challenging',3,1,'Which task is most challenging?',['solving a new proof that requires several steps','copying one familiar word','sitting still for a moment'],'solving a new proof that requires several steps','需要多步推理的新证明会考验能力。'),q('challenging',4,2,'“She answered in a challenging tone” suggests she sounded?',['questioning or defiant','grateful and apologetic','too quiet to hear'],'questioning or defiant','challenge 的语气义可表示质疑或挑衅。')]});
D('chambered',{etymology:e('chambered 由 chamber 加 -ed 构成；chamber 经古法语 chambre 源自拉丁语 camera“拱顶房间”，形容具有一个或多个封闭腔室的结构。','chambered'),contexts:[c('chambered.s1','动物解剖','The chambered shell of the nautilus contains a series of internal compartments, and the animal occupies only the newest outer chamber.','鹦鹉螺的多室外壳内部有一系列隔间，动物只居住在最新形成的外部腔室里。','The chambered shell of the nautilus contains a series of internal compartments / and the animal occupies only the newest outer chamber.','chambered 修饰 shell；分句说明壳内被分隔成多个腔室。','结构内部由封闭小室隔开，体现 chambered.s1。')],mistakes:[m('The chambered shell was a single solid mass with no internal spaces or partitions anywhere.','The unchambered shell was a single solid mass with no internal spaces or partitions anywhere.','没有任何内部腔室的实心结构与 chambered 相反。')],quiz:[q('chambered',1,1,'A chambered shell has?',['one or more enclosed internal compartments','a perfectly solid interior with no spaces','only a painted outer surface'],'one or more enclosed internal compartments','chambered.s1 指内部分成一个或多个腔室。'),q('chambered',2,1,'A chambered heart has?',['separate internal cavities','no hollow spaces','a metal outer coating'],'separate internal cavities','器官由腔室构成可称 chambered。'),q('chambered',3,1,'Which object is chambered?',['a shell divided internally by walls','a solid marble sphere','a flat sheet of paper'],'a shell divided internally by walls','内部隔出多个小室的外壳符合 chambered。'),q('chambered',4,1,'The word chambered is formed from chamber plus a suffix meaning?',['having or provided with','the act of removing','without any relation to'],'having or provided with','-ed 可构成具有某种结构的形容词。')]});
D('chameleon',{etymology:e('chameleon 经拉丁语 chamaeleon 来自希腊语 khamailēōn，字面上是“地上的狮子”；该名称用于能改变体色以配合环境的小型蜥蜴，后比喻善变的人。','chameleon'),contexts:[c('chameleon.s2','政治评论','Critics called the minister a political chameleon because she adopted whichever position seemed popular in each new district.','批评者称这位部长是政治变色龙，因为她在每个新选区都采取看起来最受欢迎的立场。','Critics called the minister a political chameleon / because she adopted whichever position seemed popular / in each new district.','chameleon 作宾语；because 从句解释其观点随环境改变。','为迎合不同场合而迅速改变立场，体现比喻义 s2。')],mistakes:[m('The chameleon kept the same opinions in every situation and refused to adapt them to suit anyone.','The steadfast politician kept the same opinions in every situation and refused to adapt them to suit anyone.','始终不变、拒绝适应的人不符合 chameleon 的善变比喻义。')],quiz:[q('chameleon',1,1,'A chameleon is a lizard known for its ability to?',['change its skin color','grow feathers','breathe underwater'],'change its skin color','chameleon.s1 指会改变体色的小型蜥蜴。'),q('chameleon',2,2,'A political chameleon is a person who?',['changes opinions to suit each situation','holds one position consistently','studies reptiles for a living'],'changes opinions to suit each situation','chameleon.s2 比喻随场合改变观点、立场的人。'),q('chameleon',3,1,'Which animal is a chameleon?',['a small color-changing lizard','a flightless marine mammal','a freshwater fish'],'a small color-changing lizard','变色龙属于蜥蜴。'),q('chameleon',4,2,'A colleague called a chameleon changes views mainly to?',['adapt to the people or circumstances around them','avoid ever speaking to anyone','remain identical in every debate'],'adapt to the people or circumstances around them','比喻义强调按场合变化以迎合环境。')]});
D('chandler',{etymology:e('chandler 经古法语 chandelier 来自拉丁语 candela“蜡烛”；早期 chandler 制作或售卖蜡烛，后来也指向船舶供应食物、绳索和灯具等物资的商人。','chandler'),contexts:[c('chandler.s2','航海补给','Before the vessel left port, the ship’s chandler delivered rope, lamp oil, and provisions to the crew.','船只离港前，船舶供应商向船员送来了绳索、灯油和补给。','Before the vessel left port / the ship’s chandler delivered rope, lamp oil, and provisions / to the crew.','chandler 是 delivered 的主语；ship’s 限定为船舶供应商义。','向船只供应绳索、油料与食物，体现 s2。')],mistakes:[m('The harbor chandler repaired the ship’s hull with a hammer and replaced its engine rather than selling any supplies.','The shipwright repaired the ship’s hull with a hammer and replaced its engine rather than selling any supplies.','修造船体是 shipwright 的工作；chandler 在此义是提供船舶物资的商人。')],quiz:[q('chandler',1,1,'Historically, a chandler first made or sold?',['candles','navigation charts only','musical instruments'],'candles','chandler.s1 指蜡烛制造商或销售者。'),q('chandler',2,2,'A ship’s chandler supplies?',['ships with stores such as rope and provisions','passengers with driving lessons','the harbor with fish'],'ships with stores such as rope and provisions','chandler.s2 是船舶补给商。'),q('chandler',3,1,'Which person is a chandler in the older trade sense?',['a maker selling household candles','a captain steering a vessel','a carpenter repairing a mast'],'a maker selling household candles','制作或售卖蜡烛的人是早期 chandler。'),q('chandler',4,2,'A vessel needs lamp oil and rope before sailing. It visits a?',['ship chandler','book chandler','caterpillar'],'ship chandler','船具商可供应灯油、绳索等船用物资。')]});
D('changeover',{etymology:e('changeover 是 change 与 over 组合形成的名词，20世纪英语中用于从一种方法、设备或轮班转到另一种的交接或转换。','changeover'),contexts:[c('changeover.s1','工厂排班','The factory planned the changeover from night production to daytime shifts for Sunday, when demand was low and maintenance crews were available.','工厂把从夜间生产转为白班的交接安排在星期日，因为那时需求较低且维修人员有空。','The factory planned the changeover from night production to daytime shifts for Sunday / when demand was low / and maintenance crews were available.','changeover 是 planned 的宾语；from...to...明确转换前后的安排。','生产安排从夜班转成白班，体现转换与交接义。')],mistakes:[m('The changeover kept the old production system exactly as it was and introduced no different machine, method, or shift.','The continuation kept the old production system exactly as it was and introduced no different machine, method, or shift.','没有发生任何改变或交接就不能称 changeover。')],quiz:[q('changeover',1,1,'A changeover from one system to another is?',['a switch or transition between them','a decision to keep both systems unchanged','a count of the workers'],'a switch or transition between them','changeover.s1 指从一种方法或系统转向另一种。'),q('changeover',2,1,'A television channel’s changeover may involve?',['moving from one program or service to another','repairing a river embankment','cancelling every broadcast forever'],'moving from one program or service to another','节目或服务之间的切换属于 changeover。'),q('changeover',3,1,'A shift changeover occurs when?',['one worker or team hands duty to the next','all work permanently ends','a machine is painted'],'one worker or team hands duty to the next','changeover 也可指轮班交接。'),q('changeover',4,1,'Which phrase uses changeover correctly?',['the changeover to a new payment system','the changeover that made no change at all','the changeover of a noun into a planet'],'the changeover to a new payment system','新支付系统的启用是从旧方式到新方式的转换。')]});
D('chaotic',{etymology:e('chaotic 由 chaos 加 -ic 构成；chaos 经拉丁语来自希腊语 khaos“深渊、混沌”，后来指完全无序的状态。','chaotic'),contexts:[c('chaotic.s2','工作管理','Her chaotic schedule listed three meetings at the same hour, omitted travel time, and gave no one a clear deadline.','她杂乱无章的日程把三场会议排在同一时间，漏掉路途时间，也没给任何人明确期限。','Her chaotic schedule listed three meetings at the same hour / omitted travel time / and gave no one a clear deadline.','chaotic 修饰 schedule；后续细节列举安排缺乏秩序的表现。','安排缺少计划并彼此冲突，体现日常生活或工作混乱义 s2。')],mistakes:[m('The chaotic evacuation was carefully ordered, with every family assigned a route and a precise departure time.','The well-organized evacuation was carefully ordered, with every family assigned a route and a precise departure time.','路线和时间清晰协调的撤离并非 chaotic。')],quiz:[q('chaotic',1,1,'A chaotic emergency scene is?',['disordered and out of control','quietly arranged in a clear sequence','a formal ceremony'],'disordered and out of control','chaotic.s1 指混乱且失去控制。'),q('chaotic',2,2,'A chaotic work life may be?',['poorly organized with conflicting plans','carefully scheduled and predictable','free of all activities'],'poorly organized with conflicting plans','chaotic.s2 指生活或工作安排杂乱无章。'),q('chaotic',3,1,'Which situation is chaotic?',['several alarms ring while people run in every direction','everyone follows a marked exit calmly','a single clerk files papers by date'],'several alarms ring while people run in every direction','警报与人群失序符合混乱场面义。'),q('chaotic',4,2,'A chaotic diary with overlapping appointments lacks?',['a workable plan and order','any written dates','a cover'],'a workable plan and order','相互冲突的安排体现缺乏秩序。')]});
D('chaotically',{etymology:e('chaotically 由 chaotic 去 -ic 加副词后缀 -ally 构成，修饰以混乱、无计划的方式进行的动作；chaos 源于希腊语 khaos“混沌”。','chaotically'),contexts:[c('chaotically.s1','现场秩序','When the doors opened late, passengers moved chaotically through the station, crossing queues and blocking the narrow entrances.','车站延迟开门后，乘客在站内混乱地移动，穿插队伍并堵住狭窄入口。','When the doors opened late / passengers moved chaotically through the station / crossing queues and blocking the narrow entrances.','chaotically 修饰 moved；分词短语展示行动缺乏秩序的后果。','乘客无序穿行并堵路，体现副词义。')],mistakes:[m('The files were chaotically arranged in exact alphabetical order, with every folder labeled and placed on its assigned shelf.','The files were systematically arranged in exact alphabetical order, with every folder labeled and placed on its assigned shelf.','完全按字母和指定架位整理属于有序安排，不是 chaotically。')],quiz:[q('chaotically',1,1,'To move chaotically is to move?',['without order or a plan','in a carefully rehearsed sequence','only in a straight line'],'without order or a plan','chaotically.s1 表示以混乱无序的方式。'),q('chaotically',2,1,'A desk arranged chaotically might have?',['papers scattered in unrelated piles','labeled folders in neat rows','nothing on it at all'],'papers scattered in unrelated piles','文件散乱成堆是无序摆放。'),q('chaotically',3,1,'Which verb phrase is closest in meaning to chaotically?',['in a confused, disorderly way','at a measured, regular pace','according to a precise list'],'in a confused, disorderly way','该副词说明动作杂乱、没有计划。'),q('chaotically',4,1,'The crowd dispersed chaotically after the alarm. This means it?',['broke up in a disorderly manner','left in one quiet, organized line','remained seated in assigned places'],'broke up in a disorderly manner','混乱地散开对应 chaotically。')]});
D('chapbook',{etymology:e('chapbook 由 chapman“走街串巷的商贩”与 book 组合而成；早期 chapmen 贩卖廉价通俗印刷品，故该词指小本故事、歌谣或诗集。','chapbook'),contexts:[c('chapbook.s1','印刷文化史','The historian found a chapbook of ballads printed on cheap paper and sold by a pedlar to rural readers in the eighteenth century.','历史学家发现一本廉价纸张印制的歌谣小册子，十八世纪时曾由小贩卖给乡村读者。','The historian found a chapbook of ballads / printed on cheap paper / and sold by a pedlar to rural readers in the eighteenth century.','chapbook of ballads 指歌谣小册子；过去分词短语说明其印制与销售方式。','廉价、通俗、由小贩出售的歌谣册体现 chapbook。')],mistakes:[m('The archive catalogued a 900-page luxury encyclopedia as a chapbook because it was large, expensive, and intended for specialists.','The archive catalogued a short, inexpensive booklet of popular tales as a chapbook because it was small and intended for general readers.','大部头昂贵的专业百科不符合 chapbook 的小本廉价通俗特征。')],quiz:[q('chapbook',1,1,'A historical chapbook was usually?',['a small, inexpensive booklet of popular writing','a large leather-bound legal code','a handwritten naval map'],'a small, inexpensive booklet of popular writing','chapbook.s1 指廉价通俗故事、歌谣或诗的小册子。'),q('chapbook',2,1,'A chapbook might contain?',['ballads or popular tales','computer source code only','a list of ship engines'],'ballads or popular tales','通俗歌谣和故事是 chapbook 常见内容。'),q('chapbook',3,1,'Why were chapbooks accessible to many readers?',['they were cheaply printed and sold by peddlers','they were unique royal manuscripts','they could be read only in a palace'],'they were cheaply printed and sold by peddlers','chapbook 常是便宜、易得的印刷读物。'),q('chapbook',4,1,'The first part of chapbook is historically associated with a?',['peddler or traveling seller','court judge','ship’s captain'],'peddler or traveling seller','chap 来自 chapman，即走街串巷的商贩。')]});
D('chaplain',{etymology:e('chaplain 经古法语 chapelain 源自晚期拉丁语 cappellanus，原指守护圣马丁斗篷小圣物龛 chapel 的神职人员；后指服务于机构的牧师。','chaplain'),contexts:[c('chaplain.s1','医院服务','The hospital chaplain visited patients of several faiths, offering prayer when requested and quiet conversation to anyone facing difficult news.','医院牧师探望不同信仰的患者，按请求祈祷，也陪伴任何面对坏消息的人谈心。','The hospital chaplain visited patients of several faiths / offering prayer when requested / and quiet conversation to anyone facing difficult news.','chaplain 是 visited 的主语；hospital 说明其服务机构而非普通堂区。','为医院中的患者提供精神关怀，体现机构牧师义。')],mistakes:[m('The hospital chaplain operated on patients in the operating room as the institution’s licensed surgeon.','The hospital surgeon operated on patients in the operating room as the institution’s licensed physician.','神职 chaplain 提供宗教或精神关怀，不是执业外科医生。')],quiz:[q('chaplain',1,1,'A hospital chaplain serves?',['patients and staff in a religious or spiritual role','as the hospital’s chief surgeon','as a pharmacy delivery truck'],'patients and staff in a religious or spiritual role','chaplain.s1 指服务于医院等机构的神职人员。'),q('chaplain',2,1,'Which place may have its own chaplain?',['a prison or university','a private garden with no staff','a single kitchen drawer'],'a prison or university','chaplain 可受雇于监狱、大学、医院或军队。'),q('chaplain',3,1,'A chaplain may offer a patient?',['prayer or spiritual support','a surgical diagnosis as the attending doctor','a bus ticket as a traffic officer'],'prayer or spiritual support','牧师可按请求提供祈祷和精神陪伴。'),q('chaplain',4,1,'Unlike a parish priest, an institutional chaplain is attached to?',['a hospital, college, prison, or similar institution','a particular musical instrument','a trade in candles'],'a hospital, college, prison, or similar institution','chaplain 为机构而非普通堂区服务。')]});
D('char',{etymology:e('char 的“烧焦、烧黑”义可能是 charcoal 的缩略形式；英国英语“做家务清洁”义与 charwoman 有关。两义词源不同，早期历史并非全都确定。','char'),contexts:[c('char.s2','英式用法','Two mornings a week, Mrs. Green charred for a family in the village, cleaning their kitchen and washing the floors.','格林太太每周有两个上午在村里一家人家做清洁，打扫厨房并擦洗地板。','Two mornings a week / Mrs. Green charred for a family in the village / cleaning their kitchen and washing the floors.','charred 在这里作英国英语动词，for 引出提供家务服务的对象。','打扫厨房、擦地是英国口语 char.s2 的清洁杂务义。')],mistakes:[m('The housekeeper charred the kitchen by sweeping the floor and washing the dishes without burning or blackening anything.','The housekeeper cleaned the kitchen by sweeping the floor and washing the dishes without burning or blackening anything.','句中是清洁杂务而非烧黑表面；char 的两义不可混淆。')],quiz:[q('char',1,1,'To char a pepper is to?',['burn its surface until it blackens','wash it in cold water','freeze it solid'],'burn its surface until it blackens','char.s1 指把表面烧焦或烧黑。'),q('char',2,2,'In British English, someone who chars for a household works as?',['a cleaner doing domestic jobs','a ship’s captain','a professional cellist'],'a cleaner doing domestic jobs','char.s2 是做清洁家务的英国英语用法。'),q('char',3,1,'Which cooking instruction uses char as a verb?',['Char the peppers over the flame until blistered.','Char the plates by polishing them with soap.','Char the soup by cooling it in ice.'],'Char the peppers over the flame until blistered.','火焰把辣椒表皮烧黑、起泡是 char。'),q('char',4,2,'“She chars for three neighbors” means she?',['does cleaning work for them','burns their houses','serves as their elected chair'],'does cleaning work for them','英国英语中 char for a household 指去做清洁工作。')]});
D('characterise',{etymology:e('characterise 是 character 加 -ise 构成的英式拼法；character 经拉丁语与希腊语 kharaktēr“刻痕、印记”而来，动词可指构成典型特征或刻画性质。','characterise'),contexts:[c('characterise.s2','文学评论','The novelist characterises the detective through small habits—she aligns every cup with the table edge and notices when one is moved.','小说家通过细小习惯刻画侦探：她把每只杯子都与桌沿对齐，还会注意到哪只被移动过。','The novelist characterises the detective through small habits / she aligns every cup with the table edge / and notices when one is moved.','characterises 的宾语是 the detective；through 短语说明塑造人物的方式。','通过具体习惯描写人物性格，体现 characterise.s2。')],mistakes:[m('A single brief snowfall characterises the entire desert climate, although it is rare and does not describe typical conditions.','A single brief snowfall does not characterise the entire desert climate, because it is rare and not typical.','罕见且不典型的个例不能构成某气候的典型特征。')],quiz:[q('characterise',1,1,'If long winters characterise a region, they?',['are a typical feature of it','occur there only once by accident','have no connection to its climate'],'are a typical feature of it','characterise.s1 指是某人或事物的典型特征。'),q('characterise',2,2,'A novelist characterises a hero by?',['describing the qualities that make the person distinctive','counting the book’s chapters','changing the hero’s spelling'],'describing the qualities that make the person distinctive','characterise.s2 指刻画或描述人物的特质。'),q('characterise',3,1,'Which detail could characterise a careful engineer?',['she checks each joint twice before signing off','she never inspects her work','she forgets every tool she uses'],'she checks each joint twice before signing off','反复检查接缝能体现工程师谨慎的典型特征。'),q('characterise',4,2,'Characterise is the British spelling of?',['characterize','categorise only','catalyse'],'characterize','characterise 与 characterize 是英美拼写变体。')]});
D('characterization',{etymology:e('characterization 由 characterize 加名词后缀 -ation 构成；characterize 经 character 与希腊语 kharaktēr“刻痕、印记”相关，可指文学人物塑造或对事物特征的描述。','characterization'),contexts:[c('characterization.s1','小说写作','The novel’s characterization of the nurse unfolds through her decisions under pressure, not through a paragraph listing her virtues.','小说对护士的刻画通过她在压力下的抉择逐渐展开，而不是靠一段列举优点的文字。','The novel’s characterization of the nurse unfolds through her decisions under pressure / not through a paragraph listing her virtues.','characterization of the nurse 指人物塑造；through 指呈现人物的方式。','通过行动塑造文学人物，体现 characterization.s1。')],mistakes:[m('The reviewer praised the novel’s characterization because every person remained indistinguishable, with no motives or individual traits.','The reviewer criticized the novel’s characterization because every person remained indistinguishable, with no motives or individual traits.','人物彼此无区别、没有动机特征，说明人物刻画薄弱而非值得称赞。')],quiz:[q('characterization',1,1,'In literary criticism, characterization is?',['the creation or portrayal of characters','the order in which pages are numbered','the sale of a book to a library'],'the creation or portrayal of characters','characterization.s1 指文学作品中的人物刻画。'),q('characterization',2,2,'A scientific characterization of a mineral gives?',['an account of its distinguishing qualities','a fictional plot about its childhood','the author’s signature only'],'an account of its distinguishing qualities','characterization.s2 可指对事物特点作描述。'),q('characterization',3,1,'Which sentence describes characterization?',['The author reveals her courage through the choices she makes.','The book has 240 pages.','The mineral sample weighs two grams.'],'The author reveals her courage through the choices she makes.','通过选择展现勇气是人物刻画的一种方式。'),q('characterization',4,2,'A full characterization of a chemical sample would include?',['its properties and identifying features','a cast list for a stage play','a map of the theater'],'its properties and identifying features','科学描述特征对应 characterization.s2。')]});

})();
